    { r = {"VALENTINE"}, t = "Shall not behold her face at ample view;" },
    { r = {"VALENTINE"}, t = "But like a cloistress she will veiled walk," },
    { r = {"VALENTINE"}, t = "And water once a day her chamber round" },
