    { d = "Act 1, Scene 2. The sea-coast.", h = true },
    { d = "Enter Viola, a Captain and Sailors" },
    { r = {"VIOLA"}, t = "What country, friends, is this?" },
    { r = {"SEA CAPTAIN"}, t = "This is Illyria, lady." },
    { r = {"VIOLA"}, t = "And what should I do in Illyria?" },
    { r = {"VIOLA"}, t = "My brother he is in Elysium." },
    { r = {"VIOLA"}, t = "Perchance he is not drown’d. What think you, sailors?" },
    { r = {"SEA CAPTAIN"}, t = "It is perchance that you yourself were sav’d." },
    { r = {"VIOLA"}, t = "O my poor brother! and so perchance may he be." },
    { r = {"SEA CAPTAIN"}, t = "True, madam; and to comfort you with chance," },
    { r = {"SEA CAPTAIN"}, t = "Assure yourself, after our ship did split," },
    { r = {"SEA CAPTAIN"}, t = "When you, and those poor number sav’d with you," },
    { r = {"SEA CAPTAIN"}, t = "Hung on our driving boat, I saw your brother," },
    { r = {"SEA CAPTAIN"}, t = "Most provident in peril, bind himself," },
    { r = {"SEA CAPTAIN"}, t = "(Courage and hope both teaching him the practice)" },
    { r = {"SEA CAPTAIN"}, t = "To a strong mast that liv’d upon the sea;" },
    { r = {"SEA CAPTAIN"}, t = "Where, like Arion on the dolphin’s back," },
    { r = {"SEA CAPTAIN"}, t = "I saw him hold acquaintance with the waves" },
    { r = {"SEA CAPTAIN"}, t = "So long as I could see." },
    { r = {"VIOLA"}, t = "For saying so, there’s gold!" },
    { r = {"VIOLA"}, t = "Mine own escape unfoldeth to my hope," },
    { r = {"VIOLA"}, t = "Whereto thy speech serves for authority," },
    { r = {"VIOLA"}, t = "The like of him. Know’st thou this country?" },
    { r = {"SEA CAPTAIN"}, t = "Ay, madam, well, for I was bred and born" },
    { r = {"SEA CAPTAIN"}, t = "Not three hours’ travel from this very place." },
    { r = {"VIOLA"}, t = "Who governs here?" },
    { r = {"SEA CAPTAIN"}, t = "A noble duke, in nature as in name." },
    { r = {"VIOLA"}, t = "What is his name?" },
    { r = {"SEA CAPTAIN"}, t = "Orsino." },
    { r = {"VIOLA"}, t = "Orsino! I have heard my father name him." },
    { r = {"VIOLA"}, t = "He was a bachelor then." },
    { r = {"SEA CAPTAIN"}, t = "And so is now, or was so very late;" },
    { r = {"SEA CAPTAIN"}, t = "For but a month ago I went from hence," },
    { r = {"SEA CAPTAIN"}, t = "And then ’twas fresh in murmur, (as, you know," },
    { r = {"SEA CAPTAIN"}, t = "What great ones do, the less will prattle of)" },
    { r = {"SEA CAPTAIN"}, t = "That he did seek the love of fair Olivia." },
    { r = {"VIOLA"}, t = "What’s she?" },
    { r = {"SEA CAPTAIN"}, t = "A virtuous maid, the daughter of a count" },
    { r = {"SEA CAPTAIN"}, t = "That died some twelvemonth since; then leaving her" },
    { r = {"SEA CAPTAIN"}, t = "In the protection of his son, her brother," },
    { r = {"SEA CAPTAIN"}, t = "Who shortly also died; for whose dear love" },
    { r = {"SEA CAPTAIN"}, t = "They say, she hath abjur’d the company" },
    { r = {"SEA CAPTAIN"}, t = "And sight of men." },
    { r = {"VIOLA"}, t = "O that I served that lady," },
    { r = {"VIOLA"}, t = "And might not be delivered to the world," },
    { r = {"VIOLA"}, t = "Till I had made mine own occasion mellow," },
    { r = {"VIOLA"}, t = "What my estate is." },
    { r = {"SEA CAPTAIN"}, t = "That were hard to compass," },
    { r = {"SEA CAPTAIN"}, t = "Because she will admit no kind of suit," },
    { r = {"SEA CAPTAIN"}, t = "No, not the Duke’s." },
    { r = {"VIOLA"}, t = "There is a fair behaviour in thee, Captain;" },
    { r = {"VIOLA"}, t = "And though that nature with a beauteous wall" },
    { r = {"VIOLA"}, t = "Doth oft close in pollution, yet of thee" },
    { r = {"VIOLA"}, t = "I will believe thou hast a mind that suits" },
    { r = {"VIOLA"}, t = "With this thy fair and outward character." },
    { r = {"VIOLA"}, t = "I pray thee, and I’ll pay thee bounteously," },
    { r = {"VIOLA"}, t = "Conceal me what I am, and be my aid" },
    { r = {"VIOLA"}, t = "For such disguise as haply shall become" },
    { r = {"VIOLA"}, t = "The form of my intent. I’ll serve this duke;" },
    { r = {"VIOLA"}, t = "Thou shalt present me as an eunuch to him." },
    { r = {"VIOLA"}, t = "It may be worth thy pains; for I can sing," },
    { r = {"VIOLA"}, t = "And speak to him in many sorts of music," },
    { r = {"VIOLA"}, t = "That will allow me very worth his service." },
    { r = {"VIOLA"}, t = "What else may hap, to time I will commit;" },
    { r = {"VIOLA"}, t = "Only shape thou thy silence to my wit." },
    { r = {"SEA CAPTAIN"}, t = "Be you his eunuch and your mute I’ll be;" },
    { r = {"SEA CAPTAIN"}, t = "When my tongue blabs, then let mine eyes not see." },
    { r = {"VIOLA"}, t = "I thank thee. Lead me on." },
