    { d = "Act 1, Scene 3. A Room in Olivia’s House.", h = true },
    { d = "Enter Sir Toby and Maria" },
    { r = {"SIR TOBY BELCH"}, t = "What a plague means my niece to take the death of her brother thus?" },
    { r = {"SIR TOBY BELCH"}, t = "I am sure care’s an enemy to life." },
    { r = {"MARIA"}, t = "By my troth, Sir Toby, you must come in earlier o’ nights; your cousin, my lady, takes great exceptions to your ill hours." },
    { r = {"SIR TOBY BELCH"}, t = "Why, let her except, before excepted." },
    { r = {"MARIA"}, t = "Ay, but you must confine yourself within the modest limits of order." },
    { r = {"SIR TOBY BELCH"}, t = "Confine?" },
    { r = {"SIR TOBY BELCH"}, t = "I’ll confine myself no finer than I am." },
    { r = {"SIR TOBY BELCH"}, t = "These clothes are good enough to drink in, and so be these boots too; and they be not, let them hang themselves in their own straps." },
    { r = {"MARIA"}, t = "That quaffing and drinking will undo you: I heard my lady talk of it yesterday; and of a foolish knight that you brought in one night here to be her wooer." },
    { r = {"SIR TOBY BELCH"}, t = "Who? Sir Andrew Aguecheek?" },
    { r = {"MARIA"}, t = "Ay, he." },
    { r = {"SIR TOBY BELCH"}, t = "He’s as tall a man as any’s in Illyria." },
    { r = {"MARIA"}, t = "What’s that to th’ purpose?" },
    { r = {"SIR TOBY BELCH"}, t = "Why, he has three thousand ducats a year." },
    { r = {"MARIA"}, t = "Ay, but he’ll have but a year in all these ducats." },
    { r = {"MARIA"}, t = "He’s a very fool, and a prodigal." },
    { r = {"SIR TOBY BELCH"}, t = "Fie, that you’ll say so! he plays o’ the viol-de-gamboys, and speaks three or four languages word for word without book, and hath all the good gifts of nature." },
    { r = {"MARIA"}, t = "He hath indeed, almost natural: for, besides that he’s a fool, he’s a great quarreller;" },
    { r = {"MARIA"}, t = "and, but that he hath the gift of a coward to allay the gust he hath in quarrelling, ’tis thought among the prudent he would quickly have the gift of a grave." },
    { r = {"SIR TOBY BELCH"}, t = "By this hand, they are scoundrels and substractors that say so of him." },
    { r = {"SIR TOBY BELCH"}, t = "Who are they?" },
    { r = {"MARIA"}, t = "They that add, moreover, he’s drunk nightly in your company." },
    { r = {"SIR TOBY BELCH"}, t = "With drinking healths to my niece; I’ll drink to her as long as there is a passage in my throat, and drink in Illyria." },
    { r = {"SIR TOBY BELCH"}, t = "He’s a coward and a coystril that will not drink to my niece till his brains turn o’ the toe like a parish top." },
    { r = {"SIR TOBY BELCH"}, t = "What, wench!" },
    { r = {"SIR TOBY BELCH"}, t = "Castiliano vulgo: for here comes Sir Andrew Agueface." },
    { d = "Enter Sir Andrew" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Sir Toby Belch! How now, Sir Toby Belch?" },
    { r = {"SIR TOBY BELCH"}, t = "Sweet Sir Andrew!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Bless you, fair shrew." },
    { r = {"MARIA"}, t = "And you too, sir." },
    { r = {"SIR TOBY BELCH"}, t = "Accost, Sir Andrew, accost." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "What’s that?" },
    { r = {"SIR TOBY BELCH"}, t = "My niece’s chamber-maid." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Good Mistress Accost, I desire better acquaintance." },
    { r = {"MARIA"}, t = "My name is Mary, sir." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Good Mistress Mary Accost," },
    { r = {"SIR TOBY BELCH"}, t = "You mistake, knight: accost is front her, board her, woo her, assail her." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "By my troth, I would not undertake her in this company." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Is that the meaning of accost?" },
    { r = {"MARIA"}, t = "Fare you well, gentlemen." },
    { r = {"SIR TOBY BELCH"}, t = "And thou let part so, Sir Andrew, would thou mightst never draw sword again." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And you part so, mistress, I would I might never draw sword again." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Fair lady, do you think you have fools in hand?" },
    { r = {"MARIA"}, t = "Sir, I have not you by the hand." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Marry, but you shall have, and here’s my hand." },
    { r = {"MARIA"}, t = "Now, sir, thought is free." },
    { r = {"MARIA"}, t = "I pray you, bring your hand to th’ buttery bar and let it drink." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Wherefore, sweetheart? What’s your metaphor?" },
    { r = {"MARIA"}, t = "It’s dry, sir." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Why, I think so; I am not such an ass but I can keep my hand dry." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "But what’s your jest?" },
    { r = {"MARIA"}, t = "A dry jest, sir." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Are you full of them?" },
    { r = {"MARIA"}, t = "Ay, sir, I have them at my fingers’ ends: marry, now I let go your hand, I am barren." },
    { d = "Exit Maria" },
    { r = {"SIR TOBY BELCH"}, t = "O knight, thou lack’st a cup of canary: When did I see thee so put down?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Never in your life, I think, unless you see canary put me down." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Methinks sometimes I have no more wit than a Christian or an ordinary man has; but I am a great eater of beef, and I believe that does harm to my wit." },
    { r = {"SIR TOBY BELCH"}, t = "No question." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And I thought that, I’d forswear it. I’ll ride home tomorrow, Sir Toby." },
    { r = {"SIR TOBY BELCH"}, t = "Pourquoy, my dear knight?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "What is pourquoy?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Do, or not do?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I would I had bestowed that time in the tongues that I have in fencing, dancing, and bear-baiting." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "O, had I but followed the arts!" },
    { r = {"SIR TOBY BELCH"}, t = "Then hadst thou had an excellent head of hair." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Why, would that have mended my hair?" },
    { r = {"SIR TOBY BELCH"}, t = "Past question; for thou seest it will not curl by nature." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "But it becomes me well enough, does’t not?" },
    { r = {"SIR TOBY BELCH"}, t = "Excellent, it hangs like flax on a distaff; and I hope to see a huswife take thee between her legs, and spin it off." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Faith, I’ll home tomorrow, Sir Toby; your niece will not be seen, or if she be, it’s four to one she’ll none of me; the Count himself here hard by woos her." },
    { r = {"SIR TOBY BELCH"}, t = "She’ll none o’ the Count; she’ll not match above her degree, neither in estate, years, nor wit; I have heard her swear’t." },
    { r = {"SIR TOBY BELCH"}, t = "Tut, there’s life in’t, man." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I’ll stay a month longer." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I am a fellow o’ the strangest mind i’ the world; I delight in masques and revels sometimes altogether." },
    { r = {"SIR TOBY BELCH"}, t = "Art thou good at these kick-shawses, knight?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "As any man in Illyria, whatsoever he be, under the degree of my betters; and yet I will not compare with an old man." },
    { r = {"SIR TOBY BELCH"}, t = "What is thy excellence in a galliard, knight?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Faith, I can cut a caper." },
    { r = {"SIR TOBY BELCH"}, t = "And I can cut the mutton to’t." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And I think I have the back-trick simply as strong as any man in Illyria." },
    { r = {"SIR TOBY BELCH"}, t = "Wherefore are these things hid?" },
    { r = {"SIR TOBY BELCH"}, t = "Wherefore have these gifts a curtain before ’em?" },
    { r = {"SIR TOBY BELCH"}, t = "Are they like to take dust, like Mistress Mall’s picture?" },
    { r = {"SIR TOBY BELCH"}, t = "Why dost thou not go to church in a galliard, and come home in a coranto?" },
    { r = {"SIR TOBY BELCH"}, t = "My very walk should be a jig; I would not so much as make water but in a sink-a-pace." },
    { r = {"SIR TOBY BELCH"}, t = "What dost thou mean?" },
    { r = {"SIR TOBY BELCH"}, t = "Is it a world to hide virtues in?" },
    { r = {"SIR TOBY BELCH"}, t = "I did think, by the excellent constitution of thy leg, it was formed under the star of a galliard." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Ay, ’tis strong, and it does indifferent well in a dam’d-colour’d stock." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Shall we set about some revels?" },
    { r = {"SIR TOBY BELCH"}, t = "What shall we do else? Were we not born under Taurus?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Taurus? That’s sides and heart." },
    { r = {"SIR TOBY BELCH"}, t = "No, sir, it is legs and thighs." },
    { r = {"SIR TOBY BELCH"}, t = "Let me see thee caper." },
    { r = {"SIR TOBY BELCH"}, t = "Ha, higher: ha, ha, excellent!" },
    { d = "Exeunt" },
    { d = "Act 1, Scene 4. A Room in the Duke’s Palace.", h = true },
    { d = "Enter Valentine and Viola in man’s attire" },
    { r = {"VALENTINE"}, t = "If the duke continue these favours towards you, Cesario, you are like to be much advanced; he hath known you but three days, and already you are no stranger." },
    { r = {"VIOLA"}, t = "You either fear his humour or my negligence, that you call in question the continuance of his love." },
    { r = {"VIOLA"}, t = "Is he inconstant, sir, in his favours?" },
    { r = {"VALENTINE"}, t = "No, believe me." },
    { d = "Enter Duke, Curio and Attendants" },
    { r = {"VIOLA"}, t = "I thank you. Here comes the Count." },
    { r = {"ORSINO"}, t = "Who saw Cesario, ho?" },
    { r = {"VIOLA"}, t = "On your attendance, my lord, here." },
    { r = {"ORSINO"}, t = "Stand you awhile aloof.—Cesario," },
    { r = {"ORSINO"}, t = "Thou know’st no less but all; I have unclasp’d" },
    { r = {"ORSINO"}, t = "To thee the book even of my secret soul." },
    { r = {"ORSINO"}, t = "Therefore, good youth, address thy gait unto her," },
    { r = {"ORSINO"}, t = "Be not denied access, stand at her doors," },
    { r = {"ORSINO"}, t = "And tell them, there thy fixed foot shall grow" },
    { r = {"ORSINO"}, t = "Till thou have audience." },
    { r = {"VIOLA"}, t = "Sure, my noble lord," },
    { r = {"VIOLA"}, t = "If she be so abandon’d to her sorrow" },
    { r = {"VIOLA"}, t = "As it is spoke, she never will admit me." },
    { r = {"ORSINO"}, t = "Be clamorous and leap all civil bounds," },
    { r = {"ORSINO"}, t = "Rather than make unprofited return." },
    { r = {"VIOLA"}, t = "Say I do speak with her, my lord, what then?" },
    { r = {"ORSINO"}, t = "O then unfold the passion of my love," },
    { r = {"ORSINO"}, t = "Surprise her with discourse of my dear faith;" },
    { r = {"ORSINO"}, t = "It shall become thee well to act my woes;" },
    { r = {"ORSINO"}, t = "She will attend it better in thy youth," },
    { r = {"ORSINO"}, t = "Than in a nuncio’s of more grave aspect." },
    { r = {"VIOLA"}, t = "I think not so, my lord." },
    { r = {"ORSINO"}, t = "Dear lad, believe it;" },
    { r = {"ORSINO"}, t = "For they shall yet belie thy happy years," },
    { r = {"ORSINO"}, t = "That say thou art a man: Diana’s lip" },
    { r = {"ORSINO"}, t = "Is not more smooth and rubious; thy small pipe" },
    { r = {"ORSINO"}, t = "Is as the maiden’s organ, shrill and sound," },
    { r = {"ORSINO"}, t = "And all is semblative a woman’s part." },
    { r = {"ORSINO"}, t = "I know thy constellation is right apt" },
    { r = {"ORSINO"}, t = "For this affair. Some four or five attend him:" },
    { r = {"ORSINO"}, t = "All, if you will; for I myself am best" },
    { r = {"ORSINO"}, t = "When least in company. Prosper well in this," },
    { r = {"ORSINO"}, t = "And thou shalt live as freely as thy lord," },
    { r = {"ORSINO"}, t = "To call his fortunes thine." },
    { r = {"VIOLA"}, t = "I’ll do my best" },
    { r = {"VIOLA"}, t = "To woo your lady." },
    { r = {"VIOLA"}, t = "Yet, a barful strife!", d = "Aside" },
    { r = {"VIOLA"}, t = "Whoe’er I woo, myself would be his wife." },
    { d = "Exeunt" },
    { d = "Act 1, Scene 5. A Room in Olivia’s House.", h = true },
    { d = "Enter Maria and Clown" },
    { r = {"MARIA"}, t = "Nay; either tell me where thou hast been, or I will not open my lips so wide as a bristle may enter, in way of thy excuse: my lady will hang thee for thy absence." },
    { r = {"CLOWN"}, t = "Let her hang me: he that is well hanged in this world needs to fear no colours." },
    { r = {"MARIA"}, t = "Make that good." },
    { r = {"CLOWN"}, t = "He shall see none to fear." },
    { r = {"MARIA"}, t = "A good lenten answer." },
    { r = {"MARIA"}, t = "I can tell thee where that saying was born, of I fear no colours." },
    { r = {"CLOWN"}, t = "Where, good Mistress Mary?" },
    { r = {"MARIA"}, t = "In the wars, and that may you be bold to say in your foolery." },
    { r = {"CLOWN"}, t = "Well, God give them wisdom that have it; and those that are fools, let them use their talents." },
    { r = {"MARIA"}, t = "Yet you will be hanged for being so long absent; or to be turned away; is not that as good as a hanging to you?" },
    { r = {"CLOWN"}, t = "Many a good hanging prevents a bad marriage; and for turning away, let summer bear it out." },
    { r = {"MARIA"}, t = "You are resolute then?" },
    { r = {"CLOWN"}, t = "Not so, neither, but I am resolved on two points." },
    { r = {"MARIA"}, t = "That if one break, the other will hold; or if both break, your gaskins fall." },
    { r = {"CLOWN"}, t = "Apt, in good faith, very apt!" },
    { r = {"CLOWN"}, t = "Well, go thy way; if Sir Toby would leave drinking, thou wert as witty a piece of Eve’s flesh as any in Illyria." },
    { r = {"MARIA"}, t = "Peace, you rogue, no more o’ that." },
    { r = {"MARIA"}, t = "Here comes my lady: make your excuse wisely, you were best." },
    { d = "Exit" },
    { d = "Enter Olivia with Malvolio" },
    { r = {"CLOWN"}, t = "Wit, and’t be thy will, put me into good fooling!" },
    { r = {"CLOWN"}, t = "Those wits that think they have thee, do very oft prove fools; and I that am sure I lack thee, may pass for a wise man." },
    { r = {"CLOWN"}, t = "For what says Quinapalus?" },
    { r = {"CLOWN"}, t = "Better a witty fool than a foolish wit." },
    { r = {"CLOWN"}, t = "God bless thee, lady!" },
    { r = {"OLIVIA"}, t = "Take the fool away." },
    { r = {"CLOWN"}, t = "Do you not hear, fellows? Take away the lady." },
    { r = {"OLIVIA"}, t = "Go to, y’are a dry fool; I’ll no more of you." },
    { r = {"OLIVIA"}, t = "Besides, you grow dishonest." },
    { r = {"CLOWN"}, t = "Two faults, madonna, that drink and good counsel will amend: for give the dry fool drink, then is the fool not dry; bid the dishonest man mend himself, if he mend, he is no longer dishonest; if he cannot, let the botcher mend him." },
    { r = {"CLOWN"}, t = "Anything that’s mended is but patched; virtue that transgresses is but patched with sin, and sin that amends is but patched with virtue." },
    { r = {"CLOWN"}, t = "If that this simple syllogism will serve, so; if it will not, what remedy?" },
    { r = {"CLOWN"}, t = "As there is no true cuckold but calamity, so beauty’s a flower." },
    { r = {"CLOWN"}, t = "The lady bade take away the fool, therefore, I say again, take her away." },
    { r = {"OLIVIA"}, t = "Sir, I bade them take away you." },
    { r = {"CLOWN"}, t = "Misprision in the highest degree!" },
    { r = {"CLOWN"}, t = "Lady, cucullus non facit monachum: that’s as much to say, I wear not motley in my brain." },
    { r = {"CLOWN"}, t = "Good madonna, give me leave to prove you a fool." },
    { r = {"OLIVIA"}, t = "Can you do it?" },
    { r = {"CLOWN"}, t = "Dexteriously, good madonna." },
    { r = {"OLIVIA"}, t = "Make your proof." },
    { r = {"CLOWN"}, t = "I must catechize you for it, madonna." },
    { r = {"CLOWN"}, t = "Good my mouse of virtue, answer me." },
    { r = {"OLIVIA"}, t = "Well sir, for want of other idleness, I’ll ’bide your proof." },
    { r = {"CLOWN"}, t = "Good madonna, why mourn’st thou?" },
    { r = {"OLIVIA"}, t = "Good fool, for my brother’s death." },
    { r = {"CLOWN"}, t = "I think his soul is in hell, madonna." },
    { r = {"OLIVIA"}, t = "I know his soul is in heaven, fool." },
    { r = {"CLOWN"}, t = "The more fool you, madonna, to mourn for your brother’s soul being in heaven." },
    { r = {"CLOWN"}, t = "Take away the fool, gentlemen." },
    { r = {"OLIVIA"}, t = "What think you of this fool, Malvolio? doth he not mend?" },
    { r = {"MALVOLIO"}, t = "Yes; and shall do, till the pangs of death shake him." },
    { r = {"MALVOLIO"}, t = "Infirmity, that decays the wise, doth ever make the better fool." },
    { r = {"CLOWN"}, t = "God send you, sir, a speedy infirmity, for the better increasing your folly!" },
    { r = {"CLOWN"}, t = "Sir Toby will be sworn that I am no fox; but he will not pass his word for twopence that you are no fool." },
    { r = {"OLIVIA"}, t = "How say you to that, Malvolio?" },
    { r = {"MALVOLIO"}, t = "I marvel your ladyship takes delight in such a barren rascal; I saw him put down the other day with an ordinary fool, that has no more brain than a stone." },
    { r = {"MALVOLIO"}, t = "Look you now, he’s out of his guard already; unless you laugh and minister occasion to him, he is gagged." },
    { r = {"MALVOLIO"}, t = "I protest I take these wise men, that crow so at these set kind of fools, no better than the fools’ zanies." },
    { r = {"OLIVIA"}, t = "O, you are sick of self-love, Malvolio, and taste with a distempered appetite." },
    { r = {"OLIVIA"}, t = "To be generous, guiltless, and of free disposition, is to take those things for bird-bolts that you deem cannon bullets." },
    { r = {"OLIVIA"}, t = "There is no slander in an allowed fool, though he do nothing but rail; nor no railing in a known discreet man, though he do nothing but reprove." },
    { r = {"CLOWN"}, t = "Now Mercury endue thee with leasing, for thou speak’st well of fools!" },
    { d = "Enter Maria" },
    { r = {"MARIA"}, t = "Madam, there is at the gate a young gentleman much desires to speak with you." },
    { r = {"OLIVIA"}, t = "From the Count Orsino, is it?" },
    { r = {"MARIA"}, t = "I know not, madam; ’tis a fair young man, and well attended." },
    { r = {"OLIVIA"}, t = "Who of my people hold him in delay?" },
    { r = {"MARIA"}, t = "Sir Toby, madam, your kinsman." },
    { r = {"OLIVIA"}, t = "Fetch him off, I pray you; he speaks nothing but madman. Fie on him!" },
    { d = "Exit Maria" },
    { r = {"OLIVIA"}, t = "Go you, Malvolio." },
    { r = {"OLIVIA"}, t = "If it be a suit from the Count, I am sick, or not at home." },
    { r = {"OLIVIA"}, t = "What you will, to dismiss it." },
    { d = "Exit Malvolio" },
    { r = {"OLIVIA"}, t = "Now you see, sir, how your fooling grows old, and people dislike it." },
    { r = {"CLOWN"}, t = "Thou hast spoke for us, madonna, as if thy eldest son should be a fool: whose skull Jove cram with brains, for here he comes, one of thy kin has a most weak pia mater." },
    { d = "Enter Sir Toby" },
    { r = {"OLIVIA"}, t = "By mine honour, half drunk. What is he at the gate, cousin?" },
    { r = {"SIR TOBY BELCH"}, t = "A gentleman." },
    { r = {"OLIVIA"}, t = "A gentleman? What gentleman?" },
    { r = {"SIR TOBY BELCH"}, t = "’Tis a gentleman here. A plague o’ these pickle-herrings! How now, sot?" },
    { r = {"CLOWN"}, t = "Good Sir Toby." },
    { r = {"OLIVIA"}, t = "Cousin, cousin, how have you come so early by this lethargy?" },
    { r = {"SIR TOBY BELCH"}, t = "Lechery! I defy lechery. There’s one at the gate." },
    { r = {"OLIVIA"}, t = "Ay, marry, what is he?" },
    { r = {"SIR TOBY BELCH"}, t = "Let him be the devil an he will, I care not: give me faith, say I." },
    { r = {"SIR TOBY BELCH"}, t = "Well, it’s all one." },
    { d = "Exit" },
    { r = {"OLIVIA"}, t = "What’s a drunken man like, fool?" },
    { r = {"CLOWN"}, t = "Like a drowned man, a fool, and a madman: one draught above heat makes him a fool, the second mads him, and a third drowns him." },
    { r = {"OLIVIA"}, t = "Go thou and seek the coroner, and let him sit o’ my coz; for he’s in the third degree of drink; he’s drowned." },
    { r = {"OLIVIA"}, t = "Go, look after him." },
    { r = {"CLOWN"}, t = "He is but mad yet, madonna; and the fool shall look to the madman." },
    { d = "Exit Clown" },
    { d = "Enter Malvolio" },
    { r = {"MALVOLIO"}, t = "Madam, yond young fellow swears he will speak with you." },
    { r = {"MALVOLIO"}, t = "I told him you were sick; he takes on him to understand so much, and therefore comes to speak with you." },
    { r = {"MALVOLIO"}, t = "I told him you were asleep; he seems to have a foreknowledge of that too, and therefore comes to speak with you." },
    { r = {"MALVOLIO"}, t = "What is to be said to him, lady?" },
    { r = {"MALVOLIO"}, t = "He’s fortified against any denial." },
    { r = {"OLIVIA"}, t = "Tell him, he shall not speak with me." },
    { r = {"MALVOLIO"}, t = "Has been told so; and he says he’ll stand at your door like a sheriff’s post, and be the supporter of a bench, but he’ll speak with you." },
    { r = {"OLIVIA"}, t = "What kind o’ man is he?" },
    { r = {"MALVOLIO"}, t = "Why, of mankind." },
    { r = {"OLIVIA"}, t = "What manner of man?" },
    { r = {"MALVOLIO"}, t = "Of very ill manner; he’ll speak with you, will you or no." },
    { r = {"OLIVIA"}, t = "Of what personage and years is he?" },
    { r = {"MALVOLIO"}, t = "Not yet old enough for a man, nor young enough for a boy; as a squash is before ’tis a peascod, or a codling, when ’tis almost an apple. ’Tis with him in standing water, between boy and man." },
    { r = {"MALVOLIO"}, t = "He is very well-favoured, and he speaks very shrewishly." },
    { r = {"MALVOLIO"}, t = "One would think his mother’s milk were scarce out of him." },
    { r = {"OLIVIA"}, t = "Let him approach. Call in my gentlewoman." },
    { r = {"MALVOLIO"}, t = "Gentlewoman, my lady calls." },
    { d = "Exit" },
    { d = "Enter Maria" },
    { r = {"OLIVIA"}, t = "Give me my veil; come, throw it o’er my face." },
    { r = {"OLIVIA"}, t = "We’ll once more hear Orsino’s embassy." },
    { d = "Enter Viola" },
    { r = {"VIOLA"}, t = "The honourable lady of the house, which is she?" },
    { r = {"OLIVIA"}, t = "Speak to me; I shall answer for her. Your will?" },
    { r = {"VIOLA"}, t = "Most radiant, exquisite, and unmatchable beauty,—I pray you, tell me if this be the lady of the house, for I never saw her." },
    { r = {"VIOLA"}, t = "I would be loath to cast away my speech; for besides that it is excellently well penned, I have taken great pains to con it." },
    { r = {"VIOLA"}, t = "Good beauties, let me sustain no scorn; I am very comptible, even to the least sinister usage." },
    { r = {"OLIVIA"}, t = "Whence came you, sir?" },
    { r = {"VIOLA"}, t = "I can say little more than I have studied, and that question’s out of my part." },
    { r = {"VIOLA"}, t = "Good gentle one, give me modest assurance, if you be the lady of the house, that I may proceed in my speech." },
    { r = {"OLIVIA"}, t = "Are you a comedian?" },
    { r = {"VIOLA"}, t = "No, my profound heart: and yet, by the very fangs of malice I swear, I am not that I play." },
    { r = {"VIOLA"}, t = "Are you the lady of the house?" },
    { r = {"OLIVIA"}, t = "If I do not usurp myself, I am." },
    { r = {"VIOLA"}, t = "Most certain, if you are she, you do usurp yourself; for what is yours to bestow is not yours to reserve." },
    { r = {"VIOLA"}, t = "But this is from my commission." },
    { r = {"VIOLA"}, t = "I will on with my speech in your praise, and then show you the heart of my message." },
    { r = {"OLIVIA"}, t = "Come to what is important in’t: I forgive you the praise." },
    { r = {"VIOLA"}, t = "Alas, I took great pains to study it, and ’tis poetical." },
    { r = {"OLIVIA"}, t = "It is the more like to be feigned; I pray you keep it in." },
    { r = {"OLIVIA"}, t = "I heard you were saucy at my gates; and allowed your approach, rather to wonder at you than to hear you." },
    { r = {"OLIVIA"}, t = "If you be mad, be gone; if you have reason, be brief: ’tis not that time of moon with me to make one in so skipping a dialogue." },
    { r = {"MARIA"}, t = "Will you hoist sail, sir? Here lies your way." },
    { r = {"VIOLA"}, t = "No, good swabber, I am to hull here a little longer." },
    { r = {"VIOLA"}, t = "Some mollification for your giant, sweet lady." },
    { r = {"VIOLA"}, t = "Tell me your mind." },
    { r = {"VIOLA"}, t = "I am a messenger." },
    { r = {"OLIVIA"}, t = "Sure, you have some hideous matter to deliver, when the courtesy of it is so fearful." },
    { r = {"OLIVIA"}, t = "Speak your office." },
    { r = {"VIOLA"}, t = "It alone concerns your ear." },
    { r = {"VIOLA"}, t = "I bring no overture of war, no taxation of homage; I hold the olive in my hand: my words are as full of peace as matter." },
    { r = {"OLIVIA"}, t = "Yet you began rudely. What are you? What would you?" },
    { r = {"VIOLA"}, t = "The rudeness that hath appeared in me have I learned from my entertainment." },
    { r = {"VIOLA"}, t = "What I am and what I would are as secret as maidenhead: to your ears, divinity; to any other’s, profanation." },
    { r = {"OLIVIA"}, t = "Give us the place alone: we will hear this divinity." },
    { d = "Exit Maria" },
    { r = {"OLIVIA"}, t = "Now, sir, what is your text?" },
    { r = {"VIOLA"}, t = "Most sweet lady" },
    { r = {"OLIVIA"}, t = "A comfortable doctrine, and much may be said of it." },
    { r = {"OLIVIA"}, t = "Where lies your text?" },
    { r = {"VIOLA"}, t = "In Orsino’s bosom." },
    { r = {"OLIVIA"}, t = "In his bosom? In what chapter of his bosom?" },
    { r = {"VIOLA"}, t = "To answer by the method, in the first of his heart." },
    { r = {"OLIVIA"}, t = "O, I have read it; it is heresy. Have you no more to say?" },
    { r = {"VIOLA"}, t = "Good madam, let me see your face." },
    { r = {"OLIVIA"}, t = "Have you any commission from your lord to negotiate with my face?" },
    { r = {"OLIVIA"}, t = "You are now out of your text: but we will draw the curtain and show you the picture." },
    { r = {"OLIVIA"}, t = "Look you, sir, such a one I was this present.", d = "Unveiling" },
    { r = {"OLIVIA"}, t = "Is’t not well done?" },
    { r = {"VIOLA"}, t = "Excellently done, if God did all." },
    { r = {"OLIVIA"}, t = "’Tis in grain, sir; ’twill endure wind and weather." },
    { r = {"VIOLA"}, t = "’Tis beauty truly blent, whose red and white" },
    { r = {"VIOLA"}, t = "Nature’s own sweet and cunning hand laid on." },
    { r = {"VIOLA"}, t = "Lady, you are the cruel’st she alive" },
    { r = {"VIOLA"}, t = "If you will lead these graces to the grave," },
    { r = {"VIOLA"}, t = "And leave the world no copy." },
    { r = {"OLIVIA"}, t = "O, sir, I will not be so hard-hearted; I will give out divers schedules of my beauty." },
    { r = {"OLIVIA"}, t = "It shall be inventoried and every particle and utensil labelled to my will: as, item, two lips indifferent red; item, two grey eyes with lids to them; item, one neck, one chin, and so forth." },
    { r = {"OLIVIA"}, t = "Were you sent hither to praise me?" },
    { r = {"VIOLA"}, t = "I see you what you are, you are too proud;" },
    { r = {"VIOLA"}, t = "But, if you were the devil, you are fair." },
    { r = {"VIOLA"}, t = "My lord and master loves you. O, such love" },
    { r = {"VIOLA"}, t = "Could be but recompens’d though you were crown’d" },
    { r = {"VIOLA"}, t = "The nonpareil of beauty!" },
    { r = {"OLIVIA"}, t = "How does he love me?" },
    { r = {"VIOLA"}, t = "With adorations, fertile tears," },
    { r = {"VIOLA"}, t = "With groans that thunder love, with sighs of fire." },
    { r = {"OLIVIA"}, t = "Your lord does know my mind, I cannot love him:" },
    { r = {"OLIVIA"}, t = "Yet I suppose him virtuous, know him noble," },
    { r = {"OLIVIA"}, t = "Of great estate, of fresh and stainless youth;" },
    { r = {"OLIVIA"}, t = "In voices well divulg’d, free, learn’d, and valiant," },
    { r = {"OLIVIA"}, t = "And in dimension and the shape of nature," },
    { r = {"OLIVIA"}, t = "A gracious person. But yet I cannot love him." },
    { r = {"OLIVIA"}, t = "He might have took his answer long ago." },
    { r = {"VIOLA"}, t = "If I did love you in my master’s flame," },
    { r = {"VIOLA"}, t = "With such a suff’ring, such a deadly life," },
    { r = {"VIOLA"}, t = "In your denial I would find no sense," },
    { r = {"VIOLA"}, t = "I would not understand it." },
    { r = {"OLIVIA"}, t = "Why, what would you?" },
    { r = {"VIOLA"}, t = "Make me a willow cabin at your gate," },
    { r = {"VIOLA"}, t = "And call upon my soul within the house;" },
    { r = {"VIOLA"}, t = "Write loyal cantons of contemned love," },
    { r = {"VIOLA"}, t = "And sing them loud even in the dead of night;" },
    { r = {"VIOLA"}, t = "Hallow your name to the reverberate hills," },
    { r = {"VIOLA"}, t = "And make the babbling gossip of the air" },
    { r = {"VIOLA"}, t = "Cry out Olivia! O, you should not rest" },
    { r = {"VIOLA"}, t = "Between the elements of air and earth," },
    { r = {"VIOLA"}, t = "But you should pity me." },
    { r = {"OLIVIA"}, t = "You might do much." },
    { r = {"OLIVIA"}, t = "What is your parentage?" },
    { r = {"VIOLA"}, t = "Above my fortunes, yet my state is well:" },
    { r = {"VIOLA"}, t = "I am a gentleman." },
    { r = {"OLIVIA"}, t = "Get you to your lord;" },
    { r = {"OLIVIA"}, t = "I cannot love him: let him send no more," },
    { r = {"OLIVIA"}, t = "Unless, perchance, you come to me again," },
    { r = {"OLIVIA"}, t = "To tell me how he takes it. Fare you well:" },
    { r = {"OLIVIA"}, t = "I thank you for your pains: spend this for me." },
    { r = {"VIOLA"}, t = "I am no fee’d post, lady; keep your purse;" },
    { r = {"VIOLA"}, t = "My master, not myself, lacks recompense." },
    { r = {"VIOLA"}, t = "Love make his heart of flint that you shall love," },
    { r = {"VIOLA"}, t = "And let your fervour like my master’s be" },
    { r = {"VIOLA"}, t = "Plac’d in contempt. Farewell, fair cruelty." },
    { d = "Exit" },
    { r = {"OLIVIA"}, t = "What is your parentage?" },
    { r = {"OLIVIA"}, t = "‘Above my fortunes, yet my state is well:" },
    { r = {"OLIVIA"}, t = "I am a gentleman.’ I’ll be sworn thou art;" },
    { r = {"OLIVIA"}, t = "Thy tongue, thy face, thy limbs, actions, and spirit," },
    { r = {"OLIVIA"}, t = "Do give thee five-fold blazon. Not too fast: soft, soft!" },
    { r = {"OLIVIA"}, t = "Unless the master were the man. How now?" },
    { r = {"OLIVIA"}, t = "Even so quickly may one catch the plague?" },
    { r = {"OLIVIA"}, t = "Methinks I feel this youth’s perfections" },
    { r = {"OLIVIA"}, t = "With an invisible and subtle stealth" },
    { r = {"OLIVIA"}, t = "To creep in at mine eyes. Well, let it be." },
    { r = {"OLIVIA"}, t = "What ho, Malvolio!" },
    { d = "Enter Malvolio" },
    { r = {"MALVOLIO"}, t = "Here, madam, at your service." },
    { r = {"OLIVIA"}, t = "Run after that same peevish messenger" },
    { r = {"OLIVIA"}, t = "The County’s man: he left this ring behind him," },
    { r = {"OLIVIA"}, t = "Would I or not; tell him, I’ll none of it." },
    { r = {"OLIVIA"}, t = "Desire him not to flatter with his lord," },
    { r = {"OLIVIA"}, t = "Nor hold him up with hopes; I am not for him." },
    { r = {"OLIVIA"}, t = "If that the youth will come this way tomorrow," },
    { r = {"OLIVIA"}, t = "I’ll give him reasons for’t. Hie thee, Malvolio." },
    { r = {"MALVOLIO"}, t = "Madam, I will." },
    { d = "Exit" },
    { r = {"OLIVIA"}, t = "I do I know not what, and fear to find" },
    { r = {"OLIVIA"}, t = "Mine eye too great a flatterer for my mind." },
    { r = {"OLIVIA"}, t = "Fate, show thy force, ourselves we do not owe." },
    { r = {"OLIVIA"}, t = "What is decreed must be; and be this so!" },
    { d = "Exit" },
    { d = "Act 2, Scene 1. The sea-coast.", h = true },
    { d = "Enter Antonio and Sebastian" },
    { r = {"ANTONIO"}, t = "Will you stay no longer? Nor will you not that I go with you?" },
    { r = {"SEBASTIAN"}, t = "By your patience, no; my stars shine darkly over me; the malignancy of my fate might perhaps distemper yours; therefore I shall crave of you your leave that I may bear my evils alone." },
    { r = {"SEBASTIAN"}, t = "It were a bad recompense for your love, to lay any of them on you." },
    { r = {"ANTONIO"}, t = "Let me know of you whither you are bound." },
    { r = {"SEBASTIAN"}, t = "No, sooth, sir; my determinate voyage is mere extravagancy." },
    { r = {"SEBASTIAN"}, t = "But I perceive in you so excellent a touch of modesty, that you will not extort from me what I am willing to keep in." },
    { r = {"SEBASTIAN"}, t = "Therefore it charges me in manners the rather to express myself." },
    { r = {"SEBASTIAN"}, t = "You must know of me then, Antonio, my name is Sebastian, which I called Roderigo; my father was that Sebastian of Messaline whom I know you have heard of." },
    { r = {"SEBASTIAN"}, t = "He left behind him myself and a sister, both born in an hour." },
    { r = {"SEBASTIAN"}, t = "If the heavens had been pleased, would we had so ended!" },
    { r = {"SEBASTIAN"}, t = "But you, sir, altered that, for some hour before you took me from the breach of the sea was my sister drowned." },
    { r = {"ANTONIO"}, t = "Alas the day!" },
    { r = {"SEBASTIAN"}, t = "A lady, sir, though it was said she much resembled me, was yet of many accounted beautiful." },
    { r = {"SEBASTIAN"}, t = "But though I could not with such estimable wonder overfar believe that, yet thus far I will boldly publish her, she bore a mind that envy could not but call fair." },
    { r = {"SEBASTIAN"}, t = "She is drowned already, sir, with salt water, though I seem to drown her remembrance again with more." },
    { r = {"ANTONIO"}, t = "Pardon me, sir, your bad entertainment." },
    { r = {"SEBASTIAN"}, t = "O good Antonio, forgive me your trouble." },
    { r = {"ANTONIO"}, t = "If you will not murder me for my love, let me be your servant." },
    { r = {"SEBASTIAN"}, t = "If you will not undo what you have done, that is, kill him whom you have recovered, desire it not." },
    { r = {"SEBASTIAN"}, t = "Fare ye well at once; my bosom is full of kindness, and I am yet so near the manners of my mother, that upon the least occasion more, mine eyes will tell tales of me." },
    { r = {"SEBASTIAN"}, t = "I am bound to the Count Orsino’s court: farewell." },
    { d = "Exit" },
    { r = {"ANTONIO"}, t = "The gentleness of all the gods go with thee!" },
    { r = {"ANTONIO"}, t = "I have many enemies in Orsino’s court," },
    { r = {"ANTONIO"}, t = "Else would I very shortly see thee there:" },
    { r = {"ANTONIO"}, t = "But come what may, I do adore thee so," },
    { r = {"ANTONIO"}, t = "That danger shall seem sport, and I will go." },
    { d = "Exit" },
    { d = "Act 2, Scene 2. A street.", h = true },
    { d = "Enter Viola; Malvolio at several doors" },
    { r = {"MALVOLIO"}, t = "Were you not even now with the Countess Olivia?" },
    { r = {"VIOLA"}, t = "Even now, sir; on a moderate pace I have since arrived but hither." },
    { r = {"MALVOLIO"}, t = "She returns this ring to you, sir; you might have saved me my pains, to have taken it away yourself." },
    { r = {"MALVOLIO"}, t = "She adds, moreover, that you should put your lord into a desperate assurance she will none of him." },
    { r = {"MALVOLIO"}, t = "And one thing more, that you be never so hardy to come again in his affairs, unless it be to report your lord’s taking of this." },
    { r = {"MALVOLIO"}, t = "Receive it so." },
    { r = {"VIOLA"}, t = "She took the ring of me: I’ll none of it." },
    { r = {"MALVOLIO"}, t = "Come sir, you peevishly threw it to her; and her will is it should be so returned." },
    { r = {"MALVOLIO"}, t = "If it be worth stooping for, there it lies in your eye; if not, be it his that finds it." },
    { d = "Exit" },
    { r = {"VIOLA"}, t = "I left no ring with her; what means this lady?" },
    { r = {"VIOLA"}, t = "Fortune forbid my outside have not charm’d her!" },
    { r = {"VIOLA"}, t = "She made good view of me, indeed, so much," },
    { r = {"VIOLA"}, t = "That methought her eyes had lost her tongue," },
    { r = {"VIOLA"}, t = "For she did speak in starts distractedly." },
    { r = {"VIOLA"}, t = "She loves me, sure, the cunning of her passion" },
    { r = {"VIOLA"}, t = "Invites me in this churlish messenger." },
    { r = {"VIOLA"}, t = "None of my lord’s ring? Why, he sent her none." },
    { r = {"VIOLA"}, t = "I am the man; if it be so, as ’tis," },
    { r = {"VIOLA"}, t = "Poor lady, she were better love a dream." },
    { r = {"VIOLA"}, t = "Disguise, I see thou art a wickedness" },
    { r = {"VIOLA"}, t = "Wherein the pregnant enemy does much." },
    { r = {"VIOLA"}, t = "How easy is it for the proper false" },
    { r = {"VIOLA"}, t = "In women’s waxen hearts to set their forms!" },
    { r = {"VIOLA"}, t = "Alas, our frailty is the cause, not we," },
    { r = {"VIOLA"}, t = "For such as we are made of, such we be." },
    { r = {"VIOLA"}, t = "How will this fadge? My master loves her dearly," },
    { r = {"VIOLA"}, t = "And I, poor monster, fond as much on him," },
    { r = {"VIOLA"}, t = "And she, mistaken, seems to dote on me." },
    { r = {"VIOLA"}, t = "What will become of this? As I am man," },
    { r = {"VIOLA"}, t = "My state is desperate for my master’s love;" },
    { r = {"VIOLA"}, t = "As I am woman (now alas the day!)" },
    { r = {"VIOLA"}, t = "What thriftless sighs shall poor Olivia breathe!" },
    { r = {"VIOLA"}, t = "O time, thou must untangle this, not I," },
    { r = {"VIOLA"}, t = "It is too hard a knot for me t’untie!" },
    { d = "Exit" },
    { d = "Act 2, Scene 3. A Room in Olivia’s House.", h = true },
    { d = "Enter Sir Toby and Sir Andrew" },
    { r = {"SIR TOBY BELCH"}, t = "Approach, Sir Andrew; not to be abed after midnight, is to be up betimes; and diluculo surgere, thou know’st." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Nay, by my troth, I know not; but I know to be up late is to be up late." },
    { r = {"SIR TOBY BELCH"}, t = "A false conclusion; I hate it as an unfilled can." },
    { r = {"SIR TOBY BELCH"}, t = "To be up after midnight, and to go to bed then is early: so that to go to bed after midnight is to go to bed betimes." },
    { r = {"SIR TOBY BELCH"}, t = "Does not our lives consist of the four elements?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Faith, so they say, but I think it rather consists of eating and drinking." },
    { r = {"SIR TOBY BELCH"}, t = "Th’art a scholar; let us therefore eat and drink." },
    { r = {"SIR TOBY BELCH"}, t = "Marian, I say! a stoup of wine." },
    { d = "Enter Clown" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Here comes the fool, i’ faith." },
    { r = {"CLOWN"}, t = "How now, my hearts? Did you never see the picture of “we three”?" },
    { r = {"SIR TOBY BELCH"}, t = "Welcome, ass. Now let’s have a catch." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "By my troth, the fool has an excellent breast." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I had rather than forty shillings I had such a leg, and so sweet a breath to sing, as the fool has." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "In sooth, thou wast in very gracious fooling last night when thou spok’st of Pigrogromitus, of the Vapians passing the equinoctial of Queubus; ’twas very good, i’ faith." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I sent thee sixpence for thy leman." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Hadst it?" },
    { r = {"CLOWN"}, t = "I did impeticos thy gratillity; for Malvolio’s nose is no whipstock." },
    { r = {"CLOWN"}, t = "My lady has a white hand, and the Myrmidons are no bottle-ale houses." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Excellent!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Why, this is the best fooling, when all is done." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Now, a song." },
    { r = {"SIR TOBY BELCH"}, t = "Come on, there is sixpence for you. Let’s have a song." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "There’s a testril of me too: if one knight give a" },
    { r = {"CLOWN"}, t = "Would you have a love-song, or a song of good life?" },
    { r = {"SIR TOBY BELCH"}, t = "A love-song, a love-song." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Ay, ay. I care not for good life." },
    { r = {"CLOWN"}, t = "O mistress mine, where are you roaming?", d = "sings" },
    { r = {"CLOWN"}, t = "O stay and hear, your true love’s coming," },
    { r = {"CLOWN"}, t = "That can sing both high and low." },
    { r = {"CLOWN"}, t = "Trip no further, pretty sweeting." },
    { r = {"CLOWN"}, t = "Journeys end in lovers meeting," },
    { r = {"CLOWN"}, t = "Every wise man’s son doth know." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Excellent good, i’ faith." },
    { r = {"SIR TOBY BELCH"}, t = "Good, good." },
    { r = {"CLOWN"}, t = "What is love? ’Tis not hereafter," },
    { r = {"CLOWN"}, t = "Present mirth hath present laughter." },
    { r = {"CLOWN"}, t = "What’s to come is still unsure." },
    { r = {"CLOWN"}, t = "In delay there lies no plenty," },
    { r = {"CLOWN"}, t = "Then come kiss me, sweet and twenty." },
    { r = {"CLOWN"}, t = "Youth’s a stuff will not endure." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "A mellifluous voice, as I am true knight." },
    { r = {"SIR TOBY BELCH"}, t = "A contagious breath." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Very sweet and contagious, i’ faith." },
    { r = {"SIR TOBY BELCH"}, t = "To hear by the nose, it is dulcet in contagion." },
    { r = {"SIR TOBY BELCH"}, t = "But shall we make the welkin dance indeed?" },
    { r = {"SIR TOBY BELCH"}, t = "Shall we rouse the night-owl in a catch that will draw three souls out of one weaver?" },
    { r = {"SIR TOBY BELCH"}, t = "Shall we do that?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And you love me, let’s do’t: I am dog at a catch." },
    { r = {"CLOWN"}, t = "By’r lady, sir, and some dogs will catch well." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Most certain. Let our catch be, “Thou knave.”" },
    { r = {"CLOWN"}, t = "“Hold thy peace, thou knave” knight?" },
    { r = {"CLOWN"}, t = "I shall be constrain’d in’t to call thee knave, knight." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Tis not the first time I have constrained one to call me knave." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Begin, fool; it begins “Hold thy peace.”" },
    { r = {"CLOWN"}, t = "I shall never begin if I hold my peace." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Good, i’ faith! Come, begin." },
    { d = "Catch sung" },
    { d = "Enter Maria" },
    { r = {"MARIA"}, t = "What a caterwauling do you keep here!" },
    { r = {"MARIA"}, t = "If my lady have not called up her steward Malvolio, and bid him turn you out of doors, never trust me." },
    { r = {"SIR TOBY BELCH"}, t = "My lady’s a Cataian, we are politicians, Malvolio’s a Peg-a-Ramsey, and" },
    { r = {"SIR TOBY BELCH"}, t = "Three merry men be we.", d = "Sings" },
    { r = {"SIR TOBY BELCH"}, t = "Am not I consanguineous?" },
    { r = {"SIR TOBY BELCH"}, t = "Am I not of her blood?" },
    { r = {"SIR TOBY BELCH"}, t = "Tilly-vally!" },
    { r = {"SIR TOBY BELCH"}, t = "“Lady”!" },
    { r = {"SIR TOBY BELCH"}, t = "There dwelt a man in Babylon, Lady, Lady." },
    { r = {"CLOWN"}, t = "Beshrew me, the knight’s in admirable fooling." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Ay, he does well enough if he be disposed, and so do I too; he does it with a better grace, but I do it more natural." },
    { r = {"SIR TOBY BELCH"}, t = "O’ the twelfth day of December", d = "Sings" },
    { r = {"MARIA"}, t = "For the love o’ God, peace!" },
    { d = "Enter Malvolio" },
    { r = {"MALVOLIO"}, t = "My masters, are you mad?" },
    { r = {"MALVOLIO"}, t = "Or what are you?" },
    { r = {"MALVOLIO"}, t = "Have you no wit, manners, nor honesty, but to gabble like tinkers at this time of night?" },
    { r = {"MALVOLIO"}, t = "Do ye make an ale-house of my lady’s house, that ye squeak out your coziers’ catches without any mitigation or remorse of voice?" },
    { r = {"MALVOLIO"}, t = "Is there no respect of place, persons, nor time, in you?" },
    { r = {"SIR TOBY BELCH"}, t = "We did keep time, sir, in our catches. Sneck up!" },
    { r = {"MALVOLIO"}, t = "Sir Toby, I must be round with you." },
    { r = {"MALVOLIO"}, t = "My lady bade me tell you that, though she harbours you as her kinsman she’s nothing allied to your disorders." },
    { r = {"MALVOLIO"}, t = "If you can separate yourself and your misdemeanours, you are welcome to the house; if not, and it would please you to take leave of her, she is very willing to bid you farewell." },
    { r = {"SIR TOBY BELCH"}, t = "Farewell, dear heart, since I must needs be gone.", d = "Sings" },
    { r = {"MARIA"}, t = "Nay, good Sir Toby." },
    { r = {"CLOWN"}, t = "His eyes do show his days are almost done.", d = "Sings" },
    { r = {"MALVOLIO"}, t = "Is’t even so?" },
    { r = {"SIR TOBY BELCH"}, t = "But I will never die.", d = "Sings" },
    { r = {"CLOWN"}, t = "Sir Toby, there you lie.", d = "Sings" },
    { r = {"MALVOLIO"}, t = "This is much credit to you." },
    { r = {"SIR TOBY BELCH"}, t = "Shall I bid him go?", d = "Sings" },
    { r = {"CLOWN"}, t = "What and if you do?", d = "Sings" },
    { r = {"SIR TOBY BELCH"}, t = "Shall I bid him go, and spare not?", d = "Sings" },
    { r = {"CLOWN"}, t = "O, no, no, no, no, you dare not.", d = "Sings" },
    { r = {"SIR TOBY BELCH"}, t = "Out o’ tune? sir, ye lie." },
    { r = {"SIR TOBY BELCH"}, t = "Art any more than a steward?" },
    { r = {"SIR TOBY BELCH"}, t = "Dost thou think, because thou art virtuous, there shall be no more cakes and ale?" },
    { r = {"CLOWN"}, t = "Yes, by Saint Anne, and ginger shall be hot i’ the mouth too." },
    { r = {"SIR TOBY BELCH"}, t = "Th’art i’ the right." },
    { r = {"SIR TOBY BELCH"}, t = "Go, sir, rub your chain with crumbs." },
    { r = {"SIR TOBY BELCH"}, t = "A stoup of wine, Maria!" },
    { r = {"MALVOLIO"}, t = "Mistress Mary, if you prized my lady’s favour at anything more than contempt, you would not give means for this uncivil rule; she shall know of it, by this hand." },
    { d = "Exit" },
    { r = {"MARIA"}, t = "Go shake your ears." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Twere as good a deed as to drink when a man’s a-hungry, to challenge him the field, and then to break promise with him and make a fool of him." },
    { r = {"SIR TOBY BELCH"}, t = "Do’t, knight." },
    { r = {"SIR TOBY BELCH"}, t = "I’ll write thee a challenge; or I’ll deliver thy indignation to him by word of mouth." },
    { r = {"MARIA"}, t = "Sweet Sir Toby, be patient for tonight." },
    { r = {"MARIA"}, t = "Since the youth of the Count’s was today with my lady, she is much out of quiet." },
    { r = {"MARIA"}, t = "For Monsieur" },
    { r = {"MARIA"}, t = "Malvolio, let me alone with him." },
    { r = {"MARIA"}, t = "If I do not gull him into a nayword, and make him a common recreation, do not think I have wit enough to lie straight in my bed." },
    { r = {"MARIA"}, t = "I know I can do it." },
    { r = {"SIR TOBY BELCH"}, t = "Possess us, possess us, tell us something of him." },
    { r = {"MARIA"}, t = "Marry, sir, sometimes he is a kind of Puritan." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "O, if I thought that, I’d beat him like a dog." },
    { r = {"SIR TOBY BELCH"}, t = "What, for being a Puritan? Thy exquisite reason, dear knight?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I have no exquisite reason for’t, but I have reason good enough." },
    { r = {"MARIA"}, t = "The devil a Puritan that he is, or anything constantly but a time-pleaser, an affectioned ass that cons state without book and utters it by great swarths;" },
    { r = {"MARIA"}, t = "the best persuaded of himself, so crammed (as he thinks) with excellencies, that it is his grounds of faith that all that look on him love him." },
    { r = {"MARIA"}, t = "And on that vice in him will my revenge find notable cause to work." },
    { r = {"SIR TOBY BELCH"}, t = "What wilt thou do?" },
    { r = {"MARIA"}, t = "I will drop in his way some obscure epistles of love, wherein by the colour of his beard, the shape of his leg, the manner of his gait, the expressure of his eye, forehead, and complexion, he shall find himself most feelingly personated." },
    { r = {"MARIA"}, t = "I can write very like my lady your niece; on a forgotten matter we can hardly make distinction of our hands." },
    { r = {"SIR TOBY BELCH"}, t = "Excellent! I smell a device." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I have’t in my nose too." },
    { r = {"SIR TOBY BELCH"}, t = "He shall think, by the letters that thou wilt drop, that they come from my niece, and that she is in love with him." },
    { r = {"MARIA"}, t = "My purpose is indeed a horse of that colour." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And your horse now would make him an ass." },
    { r = {"MARIA"}, t = "Ass, I doubt not." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "O ’twill be admirable!" },
    { r = {"MARIA"}, t = "Sport royal, I warrant you." },
    { r = {"MARIA"}, t = "I know my physic will work with him." },
    { r = {"MARIA"}, t = "I will plant you two, and let the fool make a third, where he shall find the letter." },
    { r = {"MARIA"}, t = "Observe his construction of it." },
    { r = {"MARIA"}, t = "For this night, to bed, and dream on the event." },
    { r = {"MARIA"}, t = "Farewell." },
    { d = "Exit" },
    { r = {"SIR TOBY BELCH"}, t = "Good night, Penthesilea." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Before me, she’s a good wench." },
    { r = {"SIR TOBY BELCH"}, t = "She’s a beagle true bred, and one that adores me. What o’ that?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I was adored once too." },
    { r = {"SIR TOBY BELCH"}, t = "Let’s to bed, knight. Thou hadst need send for more money." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "If I cannot recover your niece, I am a foul way out." },
    { r = {"SIR TOBY BELCH"}, t = "Send for money, knight; if thou hast her not i’ th’ end, call me cut." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "If I do not, never trust me, take it how you will." },
    { r = {"SIR TOBY BELCH"}, t = "Come, come, I’ll go burn some sack, ’tis too late to go to bed now." },
    { r = {"SIR TOBY BELCH"}, t = "Come, knight, come, knight." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 4. A Room in the Duke’s Palace.", h = true },
    { d = "Enter Duke, Viola, Curio and others" },
    { r = {"ORSINO"}, t = "Give me some music. Now, good morrow, friends." },
    { r = {"ORSINO"}, t = "Now, good Cesario, but that piece of song," },
    { r = {"ORSINO"}, t = "That old and antique song we heard last night;" },
    { r = {"ORSINO"}, t = "Methought it did relieve my passion much," },
    { r = {"ORSINO"}, t = "More than light airs and recollected terms" },
    { r = {"ORSINO"}, t = "Of these most brisk and giddy-paced times." },
    { r = {"ORSINO"}, t = "Come, but one verse." },
    { r = {"CURIO"}, t = "He is not here, so please your lordship, that should sing it." },
    { r = {"ORSINO"}, t = "Who was it?" },
    { r = {"CURIO"}, t = "Feste, the jester, my lord, a fool that the Lady Olivia’s father took much delight in." },
    { r = {"CURIO"}, t = "He is about the house." },
    { r = {"ORSINO"}, t = "Seek him out, and play the tune the while." },
    { d = "Exit Curio. Music plays" },
    { r = {"ORSINO"}, t = "Come hither, boy. If ever thou shalt love," },
    { r = {"ORSINO"}, t = "In the sweet pangs of it remember me:" },
    { r = {"ORSINO"}, t = "For such as I am, all true lovers are," },
    { r = {"ORSINO"}, t = "Unstaid and skittish in all motions else," },
    { r = {"ORSINO"}, t = "Save in the constant image of the creature" },
    { r = {"ORSINO"}, t = "That is belov’d. How dost thou like this tune?" },
    { r = {"VIOLA"}, t = "It gives a very echo to the seat" },
    { r = {"VIOLA"}, t = "Where love is throned." },
    { r = {"ORSINO"}, t = "Thou dost speak masterly." },
    { r = {"ORSINO"}, t = "My life upon’t, young though thou art, thine eye" },
    { r = {"ORSINO"}, t = "Hath stayed upon some favour that it loves." },
    { r = {"ORSINO"}, t = "Hath it not, boy?" },
    { r = {"VIOLA"}, t = "A little, by your favour." },
    { r = {"ORSINO"}, t = "What kind of woman is’t?" },
    { r = {"VIOLA"}, t = "Of your complexion." },
    { r = {"ORSINO"}, t = "She is not worth thee, then. What years, i’ faith?" },
    { r = {"VIOLA"}, t = "About your years, my lord." },
    { r = {"ORSINO"}, t = "Too old, by heaven! Let still the woman take" },
    { r = {"ORSINO"}, t = "An elder than herself; so wears she to him," },
    { r = {"ORSINO"}, t = "So sways she level in her husband’s heart." },
    { r = {"ORSINO"}, t = "For, boy, however we do praise ourselves," },
    { r = {"ORSINO"}, t = "Our fancies are more giddy and unfirm," },
    { r = {"ORSINO"}, t = "More longing, wavering, sooner lost and worn," },
    { r = {"ORSINO"}, t = "Than women’s are." },
    { r = {"VIOLA"}, t = "I think it well, my lord." },
    { r = {"ORSINO"}, t = "Then let thy love be younger than thyself," },
    { r = {"ORSINO"}, t = "Or thy affection cannot hold the bent:" },
    { r = {"ORSINO"}, t = "For women are as roses, whose fair flower" },
    { r = {"ORSINO"}, t = "Being once display’d, doth fall that very hour." },
    { r = {"VIOLA"}, t = "And so they are: alas, that they are so;" },
    { r = {"VIOLA"}, t = "To die, even when they to perfection grow!" },
    { d = "Enter Curio and Clown" },
    { r = {"ORSINO"}, t = "O, fellow, come, the song we had last night." },
    { r = {"ORSINO"}, t = "Mark it, Cesario, it is old and plain;" },
    { r = {"ORSINO"}, t = "The spinsters and the knitters in the sun," },
    { r = {"ORSINO"}, t = "And the free maids, that weave their thread with bones" },
    { r = {"ORSINO"}, t = "Do use to chant it: it is silly sooth," },
    { r = {"ORSINO"}, t = "And dallies with the innocence of love" },
    { r = {"ORSINO"}, t = "Like the old age." },
    { r = {"CLOWN"}, t = "Are you ready, sir?" },
    { r = {"ORSINO"}, t = "Ay; prithee, sing." },
    { d = "Music" },
    { r = {"CLOWN"}, t = "Come away, come away, death.", d = "sings" },
    { r = {"CLOWN"}, t = "And in sad cypress let me be laid." },
    { r = {"CLOWN"}, t = "Fly away, fly away, breath;" },
    { r = {"CLOWN"}, t = "I am slain by a fair cruel maid." },
    { r = {"CLOWN"}, t = "My shroud of white, stuck all with yew," },
    { r = {"CLOWN"}, t = "O, prepare it!" },
    { r = {"CLOWN"}, t = "My part of death no one so true" },
    { r = {"CLOWN"}, t = "Did share it." },
    { r = {"CLOWN"}, t = "Not a flower, not a flower sweet," },
    { r = {"CLOWN"}, t = "On my black coffin let there be strown:" },
    { r = {"CLOWN"}, t = "Not a friend, not a friend greet" },
    { r = {"CLOWN"}, t = "My poor corpse where my bones shall be thrown:" },
    { r = {"CLOWN"}, t = "A thousand thousand sighs to save," },
    { r = {"CLOWN"}, t = "Lay me, O, where" },
    { r = {"CLOWN"}, t = "Sad true lover never find my grave," },
    { r = {"CLOWN"}, t = "To weep there." },
    { r = {"ORSINO"}, t = "There’s for thy pains." },
    { r = {"CLOWN"}, t = "No pains, sir; I take pleasure in singing, sir." },
    { r = {"ORSINO"}, t = "I’ll pay thy pleasure, then." },
    { r = {"CLOWN"}, t = "Truly sir, and pleasure will be paid one time or another." },
    { r = {"ORSINO"}, t = "Give me now leave to leave thee." },
    { r = {"CLOWN"}, t = "Now the melancholy god protect thee, and the tailor make thy doublet of changeable taffeta, for thy mind is a very opal." },
    { r = {"CLOWN"}, t = "I would have men of such constancy put to sea, that their business might be everything, and their intent everywhere, for that’s it that always makes a good voyage of nothing." },
    { r = {"CLOWN"}, t = "Farewell." },
    { d = "Exit Clown" },
    { r = {"ORSINO"}, t = "Let all the rest give place." },
    { d = "Exeunt Curio and Attendants" },
    { r = {"ORSINO"}, t = "Once more, Cesario," },
    { r = {"ORSINO"}, t = "Get thee to yond same sovereign cruelty." },
    { r = {"ORSINO"}, t = "Tell her my love, more noble than the world," },
    { r = {"ORSINO"}, t = "Prizes not quantity of dirty lands;" },
    { r = {"ORSINO"}, t = "The parts that fortune hath bestow’d upon her," },
    { r = {"ORSINO"}, t = "Tell her I hold as giddily as fortune;" },
    { r = {"ORSINO"}, t = "But ’tis that miracle and queen of gems" },
    { r = {"ORSINO"}, t = "That nature pranks her in attracts my soul." },
    { r = {"VIOLA"}, t = "But if she cannot love you, sir?" },
    { r = {"ORSINO"}, t = "I cannot be so answer’d." },
    { r = {"VIOLA"}, t = "Sooth, but you must." },
    { r = {"VIOLA"}, t = "Say that some lady, as perhaps there is," },
    { r = {"VIOLA"}, t = "Hath for your love as great a pang of heart" },
    { r = {"VIOLA"}, t = "As you have for Olivia: you cannot love her;" },
    { r = {"VIOLA"}, t = "You tell her so. Must she not then be answer’d?" },
    { r = {"ORSINO"}, t = "There is no woman’s sides" },
    { r = {"ORSINO"}, t = "Can bide the beating of so strong a passion" },
    { r = {"ORSINO"}, t = "As love doth give my heart: no woman’s heart" },
    { r = {"ORSINO"}, t = "So big, to hold so much; they lack retention." },
    { r = {"ORSINO"}, t = "Alas, their love may be called appetite," },
    { r = {"ORSINO"}, t = "No motion of the liver, but the palate," },
    { r = {"ORSINO"}, t = "That suffer surfeit, cloyment, and revolt;" },
    { r = {"ORSINO"}, t = "But mine is all as hungry as the sea," },
    { r = {"ORSINO"}, t = "And can digest as much. Make no compare" },
    { r = {"ORSINO"}, t = "Between that love a woman can bear me" },
    { r = {"ORSINO"}, t = "And that I owe Olivia." },
    { r = {"VIOLA"}, t = "Ay, but I know" },
    { r = {"ORSINO"}, t = "What dost thou know?" },
    { r = {"VIOLA"}, t = "Too well what love women to men may owe." },
    { r = {"VIOLA"}, t = "In faith, they are as true of heart as we." },
    { r = {"VIOLA"}, t = "My father had a daughter loved a man," },
    { r = {"VIOLA"}, t = "As it might be perhaps, were I a woman," },
    { r = {"VIOLA"}, t = "I should your lordship." },
    { r = {"ORSINO"}, t = "And what’s her history?" },
    { r = {"VIOLA"}, t = "A blank, my lord. She never told her love," },
    { r = {"VIOLA"}, t = "But let concealment, like a worm i’ th’ bud," },
    { r = {"VIOLA"}, t = "Feed on her damask cheek: she pined in thought," },
    { r = {"VIOLA"}, t = "And with a green and yellow melancholy" },
    { r = {"VIOLA"}, t = "She sat like patience on a monument," },
    { r = {"VIOLA"}, t = "Smiling at grief. Was not this love, indeed?" },
    { r = {"VIOLA"}, t = "We men may say more, swear more, but indeed," },
    { r = {"VIOLA"}, t = "Our shows are more than will; for still we prove" },
    { r = {"VIOLA"}, t = "Much in our vows, but little in our love." },
    { r = {"ORSINO"}, t = "But died thy sister of her love, my boy?" },
    { r = {"VIOLA"}, t = "I am all the daughters of my father’s house," },
    { r = {"VIOLA"}, t = "And all the brothers too: and yet I know not." },
    { r = {"VIOLA"}, t = "Sir, shall I to this lady?" },
    { r = {"ORSINO"}, t = "Ay, that’s the theme." },
    { r = {"ORSINO"}, t = "To her in haste. Give her this jewel; say" },
    { r = {"ORSINO"}, t = "My love can give no place, bide no denay." },
    { d = "Exeunt" },
    { d = "Act 2, Scene 5. Olivia’s garden.", h = true },
    { d = "Enter Sir Toby, Sir Andrew and Fabian" },
    { r = {"SIR TOBY BELCH"}, t = "Come thy ways, Signior Fabian." },
    { r = {"FABIAN"}, t = "Nay, I’ll come." },
    { r = {"FABIAN"}, t = "If I lose a scruple of this sport, let me be boiled to death with melancholy." },
    { r = {"SIR TOBY BELCH"}, t = "Wouldst thou not be glad to have the niggardly rascally sheep-biter come by some notable shame?" },
    { r = {"FABIAN"}, t = "I would exult, man." },
    { r = {"FABIAN"}, t = "You know he brought me out o’ favour with my lady about a bear-baiting here." },
    { r = {"SIR TOBY BELCH"}, t = "To anger him we’ll have the bear again, and we will fool him black and blue, shall we not, Sir Andrew?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And we do not, it is pity of our lives." },
    { d = "Enter Maria" },
    { r = {"SIR TOBY BELCH"}, t = "Here comes the little villain. How now, my metal of India?" },
    { r = {"MARIA"}, t = "Get ye all three into the box-tree." },
    { r = {"MARIA"}, t = "Malvolio’s coming down this walk; he has been yonder i’ the sun practising behaviour to his own shadow this half hour: observe him, for the love of mockery; for I know this letter will make a contemplative idiot of him." },
    { r = {"MARIA"}, t = "Close, in the name of jesting!" },
    { r = {"MARIA"}, t = "Lie thou there;", d = "The men hide themselves" },
    { r = {"MARIA"}, t = "for here comes the trout that must be caught with tickling.", d = "Throws down a letter" },
    { d = "Exit Maria" },
    { d = "Enter Malvolio" },
    { r = {"MALVOLIO"}, t = "’Tis but fortune, all is fortune." },
    { r = {"MALVOLIO"}, t = "Maria once told me she did affect me, and I have heard herself come thus near, that should she fancy, it should be one of my complexion." },
    { r = {"MALVOLIO"}, t = "Besides, she uses me with a more exalted respect than anyone else that follows her." },
    { r = {"MALVOLIO"}, t = "What should I think on’t?" },
    { r = {"SIR TOBY BELCH"}, t = "Here’s an overweening rogue!" },
    { r = {"FABIAN"}, t = "O, peace!" },
    { r = {"FABIAN"}, t = "Contemplation makes a rare turkey-cock of him; how he jets under his advanced plumes!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Slight, I could so beat the rogue!" },
    { r = {"SIR TOBY BELCH"}, t = "Peace, I say." },
    { r = {"MALVOLIO"}, t = "To be Count Malvolio." },
    { r = {"SIR TOBY BELCH"}, t = "Ah, rogue!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Pistol him, pistol him." },
    { r = {"SIR TOBY BELCH"}, t = "Peace, peace." },
    { r = {"MALVOLIO"}, t = "There is example for’t." },
    { r = {"MALVOLIO"}, t = "The lady of the Strachy married the yeoman of the wardrobe." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Fie on him, Jezebel!" },
    { r = {"FABIAN"}, t = "O, peace! now he’s deeply in; look how imagination blows him." },
    { r = {"MALVOLIO"}, t = "Having been three months married to her, sitting in my state" },
    { r = {"SIR TOBY BELCH"}, t = "O for a stone-bow to hit him in the eye!" },
    { r = {"MALVOLIO"}, t = "Calling my officers about me, in my branched velvet gown; having come from a day-bed, where I have left Olivia sleeping." },
    { r = {"SIR TOBY BELCH"}, t = "Fire and brimstone!" },
    { r = {"FABIAN"}, t = "O, peace, peace." },
    { r = {"MALVOLIO"}, t = "And then to have the humour of state; and after a demure travel of regard, telling them I know my place as I would they should do theirs, to ask for my kinsman Toby." },
    { r = {"SIR TOBY BELCH"}, t = "Bolts and shackles!" },
    { r = {"FABIAN"}, t = "O, peace, peace, peace! Now, now." },
    { r = {"MALVOLIO"}, t = "Seven of my people, with an obedient start, make out for him." },
    { r = {"MALVOLIO"}, t = "I frown the while, and perchance wind up my watch, or play with some rich jewel." },
    { r = {"MALVOLIO"}, t = "Toby approaches; curtsies there to me" },
    { r = {"SIR TOBY BELCH"}, t = "Shall this fellow live?" },
    { r = {"FABIAN"}, t = "Though our silence be drawn from us with cars, yet peace!" },
    { r = {"MALVOLIO"}, t = "I extend my hand to him thus, quenching my familiar smile with an austere regard of control" },
    { r = {"SIR TOBY BELCH"}, t = "And does not Toby take you a blow o’ the lips then?" },
    { r = {"MALVOLIO"}, t = "Saying ‘Cousin Toby, my fortunes having cast me on your niece, give me this prerogative of speech—’" },
    { r = {"SIR TOBY BELCH"}, t = "What, what?" },
    { r = {"MALVOLIO"}, t = "‘You must amend your drunkenness.’" },
    { r = {"SIR TOBY BELCH"}, t = "Out, scab!" },
    { r = {"FABIAN"}, t = "Nay, patience, or we break the sinews of our plot." },
    { r = {"MALVOLIO"}, t = "‘Besides, you waste the treasure of your time with a foolish knight—’" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "That’s me, I warrant you." },
    { r = {"MALVOLIO"}, t = "‘One Sir Andrew.’" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I knew ’twas I, for many do call me fool." },
    { r = {"MALVOLIO"}, t = "What employment have we here?", d = "Taking up the letter" },
    { r = {"FABIAN"}, t = "Now is the woodcock near the gin." },
    { r = {"SIR TOBY BELCH"}, t = "O, peace! And the spirit of humours intimate reading aloud to him!" },
    { r = {"MALVOLIO"}, t = "By my life, this is my lady’s hand: these be her very C’s, her U’s, and her T’s, and thus makes she her great P’s." },
    { r = {"MALVOLIO"}, t = "It is in contempt of question, her hand." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Her C’s, her U’s, and her T’s. Why that?" },
    { r = {"MALVOLIO"}, t = "To the unknown beloved, this, and my good wishes.", d = "Reads" },
    { r = {"MALVOLIO"}, t = "Her very phrases!" },
    { r = {"MALVOLIO"}, t = "By your leave, wax." },
    { r = {"MALVOLIO"}, t = "Soft! and the impressure her Lucrece, with which she uses to seal: ’tis my lady." },
    { r = {"MALVOLIO"}, t = "To whom should this be?" },
    { r = {"FABIAN"}, t = "This wins him, liver and all." },
    { r = {"MALVOLIO"}, t = "Jove knows I love,", d = "Reads" },
    { r = {"MALVOLIO"}, t = "But who?" },
    { r = {"MALVOLIO"}, t = "Lips, do not move," },
    { r = {"MALVOLIO"}, t = "No man must know." },
    { r = {"MALVOLIO"}, t = "‘No man must know.’" },
    { r = {"MALVOLIO"}, t = "What follows?" },
    { r = {"MALVOLIO"}, t = "The numbers alter’d!" },
    { r = {"MALVOLIO"}, t = "‘No man must know.’—If this should be thee, Malvolio?" },
    { r = {"SIR TOBY BELCH"}, t = "Marry, hang thee, brock!" },
    { r = {"MALVOLIO"}, t = "I may command where I adore," },
    { r = {"MALVOLIO"}, t = "But silence, like a Lucrece knife," },
    { r = {"MALVOLIO"}, t = "With bloodless stroke my heart doth gore;" },
    { r = {"MALVOLIO"}, t = "M.O.A.I. doth sway my life." },
    { r = {"FABIAN"}, t = "A fustian riddle!" },
    { r = {"SIR TOBY BELCH"}, t = "Excellent wench, say I." },
    { r = {"MALVOLIO"}, t = "‘M.O.A.I. doth sway my life.’—Nay, but first let me see, let me see, let me see." },
    { r = {"FABIAN"}, t = "What dish o’ poison has she dressed him!" },
    { r = {"SIR TOBY BELCH"}, t = "And with what wing the staniel checks at it!" },
    { r = {"MALVOLIO"}, t = "‘I may command where I adore.’" },
    { r = {"MALVOLIO"}, t = "Why, she may command me: I serve her, she is my lady." },
    { r = {"MALVOLIO"}, t = "Why, this is evident to any formal capacity." },
    { r = {"MALVOLIO"}, t = "There is no obstruction in this." },
    { r = {"MALVOLIO"}, t = "And the end—what should that alphabetical position portend?" },
    { r = {"MALVOLIO"}, t = "If I could make that resemble something in me!" },
    { r = {"MALVOLIO"}, t = "Softly! ‘M.O.A.I.’" },
    { r = {"SIR TOBY BELCH"}, t = "O, ay, make up that:—he is now at a cold scent." },
    { r = {"FABIAN"}, t = "Sowter will cry upon’t for all this, though it be as rank as a fox." },
    { r = {"MALVOLIO"}, t = "‘M’—Malvolio; ‘M!’ Why, that begins my name!" },
    { r = {"FABIAN"}, t = "Did not I say he would work it out? The cur is excellent at faults." },
    { r = {"MALVOLIO"}, t = "‘M’—But then there is no consonancy in the sequel; that suffers under probation: ‘A’ should follow, but ‘O’ does." },
    { r = {"FABIAN"}, t = "And ‘O’ shall end, I hope." },
    { r = {"SIR TOBY BELCH"}, t = "Ay, or I’ll cudgel him, and make him cry ‘O!’" },
    { r = {"MALVOLIO"}, t = "And then ‘I’ comes behind." },
    { r = {"FABIAN"}, t = "Ay, and you had any eye behind you, you might see more detraction at your heels than fortunes before you." },
    { r = {"MALVOLIO"}, t = "‘M.O.A.I.’" },
    { r = {"MALVOLIO"}, t = "This simulation is not as the former: and yet, to crush this a little, it would bow to me, for every one of these letters are in my name." },
    { r = {"MALVOLIO"}, t = "Soft, here follows prose." },
    { r = {"MALVOLIO"}, t = "If this fall into thy hand, revolve.", d = "Reads" },
    { r = {"MALVOLIO"}, t = "In my stars I am above thee, but be not afraid of greatness." },
    { r = {"MALVOLIO"}, t = "Some are born great, some achieve greatness, and some have greatness thrust upon ’em." },
    { r = {"MALVOLIO"}, t = "Thy fates open their hands, let thy blood and spirit embrace them." },
    { r = {"MALVOLIO"}, t = "And, to inure thyself to what thou art like to be, cast thy humble slough and appear fresh." },
    { r = {"MALVOLIO"}, t = "Be opposite with a kinsman, surly with servants." },
    { r = {"MALVOLIO"}, t = "Let thy tongue tang arguments of state; put thyself into the trick of singularity." },
    { r = {"MALVOLIO"}, t = "She thus advises thee that sighs for thee." },
    { r = {"MALVOLIO"}, t = "Remember who commended thy yellow stockings, and wished to see thee ever cross-gartered." },
    { r = {"MALVOLIO"}, t = "I say, remember." },
    { r = {"MALVOLIO"}, t = "Go to, thou art made, if thou desir’st to be so." },
    { r = {"MALVOLIO"}, t = "If not, let me see thee a steward still, the fellow of servants, and not worthy to touch Fortune’s fingers." },
    { r = {"MALVOLIO"}, t = "Farewell." },
    { r = {"MALVOLIO"}, t = "She that would alter services with thee," },
    { r = {"MALVOLIO"}, t = "The Fortunate Unhappy." },
    { r = {"MALVOLIO"}, t = "Daylight and champian discovers not more!" },
    { r = {"MALVOLIO"}, t = "This is open." },
    { r = {"MALVOLIO"}, t = "I will be proud, I will read politic authors, I will baffle Sir Toby, I will wash off gross acquaintance, I will be point-device, the very man." },
    { r = {"MALVOLIO"}, t = "I do not now fool myself, to let imagination jade me; for every reason excites to this, that my lady loves me." },
    { r = {"MALVOLIO"}, t = "She did commend my yellow stockings of late, she did praise my leg being cross-gartered, and in this she manifests herself to my love, and with a kind of injunction, drives me to these habits of her liking." },
    { r = {"MALVOLIO"}, t = "I thank my stars, I am happy." },
    { r = {"MALVOLIO"}, t = "I will be strange, stout, in yellow stockings, and cross-gartered, even with the swiftness of putting on." },
    { r = {"MALVOLIO"}, t = "Jove and my stars be praised!—Here is yet a postscript." },
    { r = {"MALVOLIO"}, t = "Thou canst not choose but know who I am.", d = "Reads" },
    { r = {"MALVOLIO"}, t = "If thou entertain’st my love, let it appear in thy smiling; thy smiles become thee well." },
    { r = {"MALVOLIO"}, t = "Therefore in my presence still smile, dear my sweet, I prithee." },
    { r = {"MALVOLIO"}, t = "Jove, I thank thee." },
    { r = {"MALVOLIO"}, t = "I will smile, I will do everything that thou wilt have me." },
    { d = "Exit" },
    { r = {"FABIAN"}, t = "I will not give my part of this sport for a pension of thousands to be paid from the Sophy." },
    { r = {"SIR TOBY BELCH"}, t = "I could marry this wench for this device." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "So could I too." },
    { r = {"SIR TOBY BELCH"}, t = "And ask no other dowry with her but such another jest." },
    { d = "Enter Maria" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Nor I neither." },
    { r = {"FABIAN"}, t = "Here comes my noble gull-catcher." },
    { r = {"SIR TOBY BELCH"}, t = "Wilt thou set thy foot o’ my neck?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Or o’ mine either?" },
    { r = {"SIR TOBY BELCH"}, t = "Shall I play my freedom at tray-trip, and become thy bond-slave?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I’ faith, or I either?" },
    { r = {"SIR TOBY BELCH"}, t = "Why, thou hast put him in such a dream, that when the image of it leaves him he must run mad." },
    { r = {"MARIA"}, t = "Nay, but say true, does it work upon him?" },
    { r = {"SIR TOBY BELCH"}, t = "Like aqua-vitae with a midwife." },
    { r = {"MARIA"}, t = "If you will then see the fruits of the sport, mark his first approach before my lady: he will come to her in yellow stockings, and ’tis a colour she abhors, and cross-gartered, a fashion she detests;" },
    { r = {"MARIA"}, t = "and he will smile upon her, which will now be so unsuitable to her disposition, being addicted to a melancholy as she is, that it cannot but turn him into a notable contempt." },
    { r = {"MARIA"}, t = "If you will see it, follow me." },
    { r = {"SIR TOBY BELCH"}, t = "To the gates of Tartar, thou most excellent devil of wit!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I’ll make one too." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 1. Olivia’s garden.", h = true },
    { d = "Enter Viola and Clown with a tabor" },
    { r = {"VIOLA"}, t = "Save thee, friend, and thy music. Dost thou live by thy tabor?" },
    { r = {"CLOWN"}, t = "No, sir, I live by the church." },
    { r = {"VIOLA"}, t = "Art thou a churchman?" },
    { r = {"CLOWN"}, t = "No such matter, sir." },
    { r = {"CLOWN"}, t = "I do live by the church, for I do live at my house, and my house doth stand by the church." },
    { r = {"VIOLA"}, t = "So thou mayst say the king lies by a beggar, if a beggar dwell near him; or the church stands by thy tabor, if thy tabor stand by the church." },
    { r = {"CLOWN"}, t = "You have said, sir." },
    { r = {"CLOWN"}, t = "To see this age!" },
    { r = {"CLOWN"}, t = "A sentence is but a chev’ril glove to a good wit." },
    { r = {"CLOWN"}, t = "How quickly the wrong side may be turned outward!" },
    { r = {"VIOLA"}, t = "Nay, that’s certain; they that dally nicely with words may quickly make them wanton." },
    { r = {"CLOWN"}, t = "I would, therefore, my sister had had no name, sir." },
    { r = {"VIOLA"}, t = "Why, man?" },
    { r = {"CLOWN"}, t = "Why, sir, her name’s a word; and to dally with that word might make my sister wanton." },
    { r = {"CLOWN"}, t = "But indeed, words are very rascals, since bonds disgraced them." },
    { r = {"VIOLA"}, t = "Thy reason, man?" },
    { r = {"CLOWN"}, t = "Troth, sir, I can yield you none without words, and words are grown so false, I am loath to prove reason with them." },
    { r = {"VIOLA"}, t = "I warrant thou art a merry fellow, and car’st for nothing." },
    { r = {"CLOWN"}, t = "Not so, sir, I do care for something." },
    { r = {"CLOWN"}, t = "But in my conscience, sir, I do not care for you." },
    { r = {"CLOWN"}, t = "If that be to care for nothing, sir, I would it would make you invisible." },
    { r = {"VIOLA"}, t = "Art not thou the Lady Olivia’s fool?" },
    { r = {"CLOWN"}, t = "No, indeed, sir; the Lady Olivia has no folly." },
    { r = {"CLOWN"}, t = "She will keep no fool, sir, till she be married, and fools are as like husbands as pilchards are to herrings, the husband’s the bigger." },
    { r = {"CLOWN"}, t = "I am indeed not her fool, but her corrupter of words." },
    { r = {"VIOLA"}, t = "I saw thee late at the Count Orsino’s." },
    { r = {"CLOWN"}, t = "Foolery, sir, does walk about the orb like the sun; it shines everywhere." },
    { r = {"CLOWN"}, t = "I would be sorry, sir, but the fool should be as oft with your master as with my mistress." },
    { r = {"CLOWN"}, t = "I think I saw your wisdom there." },
    { r = {"VIOLA"}, t = "Nay, and thou pass upon me, I’ll no more with thee." },
    { r = {"VIOLA"}, t = "Hold, there’s expenses for thee." },
    { r = {"CLOWN"}, t = "Now Jove, in his next commodity of hair, send thee a beard!" },
    { r = {"VIOLA"}, t = "By my troth, I’ll tell thee, I am almost sick for one, though I would not have it grow on my chin." },
    { r = {"VIOLA"}, t = "Is thy lady within?" },
    { r = {"CLOWN"}, t = "Would not a pair of these have bred, sir?" },
    { r = {"VIOLA"}, t = "Yes, being kept together, and put to use." },
    { r = {"CLOWN"}, t = "I would play Lord Pandarus of Phrygia, sir, to bring a Cressida to this Troilus." },
    { r = {"VIOLA"}, t = "I understand you, sir; ’tis well begged." },
    { r = {"CLOWN"}, t = "The matter, I hope, is not great, sir, begging but a beggar: Cressida was a beggar." },
    { r = {"CLOWN"}, t = "My lady is within, sir." },
    { r = {"CLOWN"}, t = "I will conster to them whence you come; who you are and what you would are out of my welkin." },
    { r = {"CLOWN"}, t = "I might say “element”, but the word is overworn." },
    { d = "Exit" },
    { r = {"VIOLA"}, t = "This fellow is wise enough to play the fool," },
    { r = {"VIOLA"}, t = "And to do that well, craves a kind of wit:" },
    { r = {"VIOLA"}, t = "He must observe their mood on whom he jests," },
    { r = {"VIOLA"}, t = "The quality of persons, and the time," },
    { r = {"VIOLA"}, t = "And like the haggard, check at every feather" },
    { r = {"VIOLA"}, t = "That comes before his eye. This is a practice" },
    { r = {"VIOLA"}, t = "As full of labour as a wise man’s art:" },
    { r = {"VIOLA"}, t = "For folly, that he wisely shows, is fit;" },
    { r = {"VIOLA"}, t = "But wise men, folly-fall’n, quite taint their wit." },
    { d = "Enter Sir Toby and Sir Andrew" },
    { r = {"SIR TOBY BELCH"}, t = "Save you, gentleman." },
    { r = {"VIOLA"}, t = "And you, sir." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Dieu vous garde, monsieur." },
    { r = {"VIOLA"}, t = "Et vous aussi; votre serviteur." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I hope, sir, you are, and I am yours." },
    { r = {"SIR TOBY BELCH"}, t = "Will you encounter the house?" },
    { r = {"SIR TOBY BELCH"}, t = "My niece is desirous you should enter, if your trade be to her." },
    { r = {"VIOLA"}, t = "I am bound to your niece, sir, I mean, she is the list of my voyage." },
    { r = {"SIR TOBY BELCH"}, t = "Taste your legs, sir, put them to motion." },
    { r = {"VIOLA"}, t = "My legs do better understand me, sir, than I understand what you mean by bidding me taste my legs." },
    { r = {"SIR TOBY BELCH"}, t = "I mean, to go, sir, to enter." },
    { r = {"VIOLA"}, t = "I will answer you with gait and entrance: but we are prevented." },
    { d = "Enter Olivia and Maria" },
    { r = {"VIOLA"}, t = "Most excellent accomplished lady, the heavens rain odours on you!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "That youth’s a rare courtier. ‘Rain odours,’ well." },
    { r = {"VIOLA"}, t = "My matter hath no voice, lady, but to your own most pregnant and vouchsafed ear." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "‘Odours,’ ‘pregnant,’ and ‘vouchsafed.’—I’ll get ’em all three ready." },
    { r = {"OLIVIA"}, t = "Let the garden door be shut, and leave me to my hearing." },
    { d = "Exeunt Sir Toby, Sir Andrew and Maria" },
    { r = {"OLIVIA"}, t = "Give me your hand, sir." },
    { r = {"VIOLA"}, t = "My duty, madam, and most humble service." },
    { r = {"OLIVIA"}, t = "What is your name?" },
    { r = {"VIOLA"}, t = "Cesario is your servant’s name, fair princess." },
    { r = {"OLIVIA"}, t = "My servant, sir! ’Twas never merry world," },
    { r = {"OLIVIA"}, t = "Since lowly feigning was call’d compliment:" },
    { r = {"OLIVIA"}, t = "Y’are servant to the Count Orsino, youth." },
    { r = {"VIOLA"}, t = "And he is yours, and his must needs be yours." },
    { r = {"VIOLA"}, t = "Your servant’s servant is your servant, madam." },
    { r = {"OLIVIA"}, t = "For him, I think not on him: for his thoughts," },
    { r = {"OLIVIA"}, t = "Would they were blanks rather than fill’d with me!" },
    { r = {"VIOLA"}, t = "Madam, I come to whet your gentle thoughts" },
    { r = {"VIOLA"}, t = "On his behalf." },
    { r = {"OLIVIA"}, t = "O, by your leave, I pray you." },
    { r = {"OLIVIA"}, t = "I bade you never speak again of him." },
    { r = {"OLIVIA"}, t = "But would you undertake another suit," },
    { r = {"OLIVIA"}, t = "I had rather hear you to solicit that" },
    { r = {"OLIVIA"}, t = "Than music from the spheres." },
    { r = {"VIOLA"}, t = "Dear lady" },
    { r = {"OLIVIA"}, t = "Give me leave, beseech you. I did send," },
    { r = {"OLIVIA"}, t = "After the last enchantment you did here," },
    { r = {"OLIVIA"}, t = "A ring in chase of you. So did I abuse" },
    { r = {"OLIVIA"}, t = "Myself, my servant, and, I fear me, you." },
    { r = {"OLIVIA"}, t = "Under your hard construction must I sit;" },
    { r = {"OLIVIA"}, t = "To force that on you in a shameful cunning," },
    { r = {"OLIVIA"}, t = "Which you knew none of yours. What might you think?" },
    { r = {"OLIVIA"}, t = "Have you not set mine honour at the stake," },
    { r = {"OLIVIA"}, t = "And baited it with all th’ unmuzzled thoughts" },
    { r = {"OLIVIA"}, t = "That tyrannous heart can think? To one of your receiving" },
    { r = {"OLIVIA"}, t = "Enough is shown. A cypress, not a bosom," },
    { r = {"OLIVIA"}, t = "Hides my heart: so let me hear you speak." },
    { r = {"VIOLA"}, t = "I pity you." },
    { r = {"OLIVIA"}, t = "That’s a degree to love." },
    { r = {"VIOLA"}, t = "No, not a grize; for ’tis a vulgar proof" },
    { r = {"VIOLA"}, t = "That very oft we pity enemies." },
    { r = {"OLIVIA"}, t = "Why then methinks ’tis time to smile again." },
    { r = {"OLIVIA"}, t = "O world, how apt the poor are to be proud!" },
    { r = {"OLIVIA"}, t = "If one should be a prey, how much the better" },
    { r = {"OLIVIA"}, t = "To fall before the lion than the wolf!" },
    { r = {"OLIVIA"}, t = "The clock upbraids me with the waste of time.", d = "Clock strikes" },
    { r = {"OLIVIA"}, t = "Be not afraid, good youth, I will not have you." },
    { r = {"OLIVIA"}, t = "And yet, when wit and youth is come to harvest," },
    { r = {"OLIVIA"}, t = "Your wife is like to reap a proper man." },
    { r = {"OLIVIA"}, t = "There lies your way, due west." },
    { r = {"VIOLA"}, t = "Then westward ho!" },
    { r = {"VIOLA"}, t = "Grace and good disposition attend your ladyship!" },
    { r = {"VIOLA"}, t = "You’ll nothing, madam, to my lord by me?" },
    { r = {"OLIVIA"}, t = "Stay:" },
    { r = {"OLIVIA"}, t = "I prithee tell me what thou think’st of me." },
    { r = {"VIOLA"}, t = "That you do think you are not what you are." },
    { r = {"OLIVIA"}, t = "If I think so, I think the same of you." },
    { r = {"VIOLA"}, t = "Then think you right; I am not what I am." },
    { r = {"OLIVIA"}, t = "I would you were as I would have you be." },
    { r = {"VIOLA"}, t = "Would it be better, madam, than I am?" },
    { r = {"VIOLA"}, t = "I wish it might, for now I am your fool." },
    { r = {"OLIVIA"}, t = "O what a deal of scorn looks beautiful" },
    { r = {"OLIVIA"}, t = "In the contempt and anger of his lip!" },
    { r = {"OLIVIA"}, t = "A murd’rous guilt shows not itself more soon" },
    { r = {"OLIVIA"}, t = "Than love that would seem hid. Love’s night is noon." },
    { r = {"OLIVIA"}, t = "Cesario, by the roses of the spring," },
    { r = {"OLIVIA"}, t = "By maidhood, honour, truth, and everything," },
    { r = {"OLIVIA"}, t = "I love thee so, that maugre all thy pride," },
    { r = {"OLIVIA"}, t = "Nor wit nor reason can my passion hide." },
    { r = {"OLIVIA"}, t = "Do not extort thy reasons from this clause," },
    { r = {"OLIVIA"}, t = "For that I woo, thou therefore hast no cause;" },
    { r = {"OLIVIA"}, t = "But rather reason thus with reason fetter:" },
    { r = {"OLIVIA"}, t = "Love sought is good, but given unsought is better." },
    { r = {"VIOLA"}, t = "By innocence I swear, and by my youth," },
    { r = {"VIOLA"}, t = "I have one heart, one bosom, and one truth," },
    { r = {"VIOLA"}, t = "And that no woman has; nor never none" },
    { r = {"VIOLA"}, t = "Shall mistress be of it, save I alone." },
    { r = {"VIOLA"}, t = "And so adieu, good madam; never more" },
    { r = {"VIOLA"}, t = "Will I my master’s tears to you deplore." },
    { r = {"OLIVIA"}, t = "Yet come again: for thou perhaps mayst move" },
    { r = {"OLIVIA"}, t = "That heart, which now abhors, to like his love." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 2. A Room in Olivia’s House.", h = true },
    { d = "Enter Sir Toby, Sir Andrew and Fabian" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "No, faith, I’ll not stay a jot longer." },
    { r = {"SIR TOBY BELCH"}, t = "Thy reason, dear venom, give thy reason." },
    { r = {"FABIAN"}, t = "You must needs yield your reason, Sir Andrew." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Marry, I saw your niece do more favours to the Count’s servingman than ever she bestowed upon me; I saw’t i’ th’ orchard." },
    { r = {"SIR TOBY BELCH"}, t = "Did she see thee the while, old boy? Tell me that." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "As plain as I see you now." },
    { r = {"FABIAN"}, t = "This was a great argument of love in her toward you." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Slight! will you make an ass o’ me?" },
    { r = {"FABIAN"}, t = "I will prove it legitimate, sir, upon the oaths of judgment and reason." },
    { r = {"SIR TOBY BELCH"}, t = "And they have been grand-jurymen since before Noah was a sailor." },
    { r = {"FABIAN"}, t = "She did show favour to the youth in your sight only to exasperate you, to awake your dormouse valour, to put fire in your heart and brimstone in your liver." },
    { r = {"FABIAN"}, t = "You should then have accosted her, and with some excellent jests, fire-new from the mint, you should have banged the youth into dumbness." },
    { r = {"FABIAN"}, t = "This was looked for at your hand, and this was balked: the double gilt of this opportunity you let time wash off, and you are now sailed into the north of my lady’s opinion;" },
    { r = {"FABIAN"}, t = "where you will hang like an icicle on Dutchman’s beard, unless you do redeem it by some laudable attempt, either of valour or policy." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And’t be any way, it must be with valour, for policy I hate; I had as lief be a Brownist as a politician." },
    { r = {"SIR TOBY BELCH"}, t = "Why, then, build me thy fortunes upon the basis of valour." },
    { r = {"SIR TOBY BELCH"}, t = "Challenge me the Count’s youth to fight with him." },
    { r = {"SIR TOBY BELCH"}, t = "Hurt him in eleven places; my niece shall take note of it, and assure thyself there is no love-broker in the world can more prevail in man’s commendation with woman than report of valour." },
    { r = {"FABIAN"}, t = "There is no way but this, Sir Andrew." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Will either of you bear me a challenge to him?" },
    { r = {"SIR TOBY BELCH"}, t = "Go, write it in a martial hand, be curst and brief; it is no matter how witty, so it be eloquent and full of invention." },
    { r = {"SIR TOBY BELCH"}, t = "Taunt him with the licence of ink." },
    { r = {"SIR TOBY BELCH"}, t = "If thou ‘thou’st’ him some thrice, it shall not be amiss, and as many lies as will lie in thy sheet of paper, although the sheet were big enough for the bed of Ware in England, set ’em down." },
    { r = {"SIR TOBY BELCH"}, t = "Go about it." },
    { r = {"SIR TOBY BELCH"}, t = "Let there be gall enough in thy ink, though thou write with a goose-pen, no matter." },
    { r = {"SIR TOBY BELCH"}, t = "About it." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Where shall I find you?" },
    { r = {"SIR TOBY BELCH"}, t = "We’ll call thee at the cubiculo. Go." },
    { d = "Exit Sir Andrew" },
    { r = {"FABIAN"}, t = "This is a dear manikin to you, Sir Toby." },
    { r = {"SIR TOBY BELCH"}, t = "I have been dear to him, lad, some two thousand strong, or so." },
    { r = {"FABIAN"}, t = "We shall have a rare letter from him; but you’ll not deliver it." },
    { r = {"SIR TOBY BELCH"}, t = "Never trust me then." },
    { r = {"SIR TOBY BELCH"}, t = "And by all means stir on the youth to an answer." },
    { r = {"SIR TOBY BELCH"}, t = "I think oxen and wainropes cannot hale them together." },
    { r = {"SIR TOBY BELCH"}, t = "For Andrew, if he were opened and you find so much blood in his liver as will clog the foot of a flea, I’ll eat the rest of th’ anatomy." },
    { r = {"FABIAN"}, t = "And his opposite, the youth, bears in his visage no great presage of cruelty." },
    { d = "Enter Maria" },
    { r = {"SIR TOBY BELCH"}, t = "Look where the youngest wren of nine comes." },
    { r = {"MARIA"}, t = "If you desire the spleen, and will laugh yourselves into stitches, follow me." },
    { r = {"MARIA"}, t = "Yond gull Malvolio is turned heathen, a very renegado; for there is no Christian that means to be saved by believing rightly can ever believe such impossible passages of grossness." },
    { r = {"MARIA"}, t = "He’s in yellow stockings." },
    { r = {"SIR TOBY BELCH"}, t = "And cross-gartered?" },
    { r = {"MARIA"}, t = "Most villainously; like a pedant that keeps a school i’ th’ church." },
    { r = {"MARIA"}, t = "I have dogged him like his murderer." },
    { r = {"MARIA"}, t = "He does obey every point of the letter that I dropped to betray him." },
    { r = {"MARIA"}, t = "He does smile his face into more lines than is in the new map with the augmentation of the Indies." },
    { r = {"MARIA"}, t = "You have not seen such a thing as ’tis." },
    { r = {"MARIA"}, t = "I  can hardly forbear hurling things at him." },
    { r = {"MARIA"}, t = "I know my lady will strike him." },
    { r = {"MARIA"}, t = "If she do, he’ll smile and take’t for a great favour." },
    { r = {"SIR TOBY BELCH"}, t = "Come, bring us, bring us where he is." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 3. A street.", h = true },
    { d = "Enter Sebastian and Antonio" },
    { r = {"SEBASTIAN"}, t = "I would not by my will have troubled you," },
    { r = {"SEBASTIAN"}, t = "But since you make your pleasure of your pains," },
    { r = {"SEBASTIAN"}, t = "I will no further chide you." },
    { r = {"ANTONIO"}, t = "I could not stay behind you: my desire," },
    { r = {"ANTONIO"}, t = "More sharp than filed steel, did spur me forth;" },
    { r = {"ANTONIO"}, t = "And not all love to see you, though so much," },
    { r = {"ANTONIO"}, t = "As might have drawn one to a longer voyage," },
    { r = {"ANTONIO"}, t = "But jealousy what might befall your travel," },
    { r = {"ANTONIO"}, t = "Being skilless in these parts; which to a stranger," },
    { r = {"ANTONIO"}, t = "Unguided and unfriended, often prove" },
    { r = {"ANTONIO"}, t = "Rough and unhospitable. My willing love," },
    { r = {"ANTONIO"}, t = "The rather by these arguments of fear," },
    { r = {"ANTONIO"}, t = "Set forth in your pursuit." },
    { r = {"SEBASTIAN"}, t = "My kind Antonio," },
    { r = {"SEBASTIAN"}, t = "I can no other answer make but thanks," },
    { r = {"SEBASTIAN"}, t = "And thanks, and ever thanks; and oft good turns" },
    { r = {"SEBASTIAN"}, t = "Are shuffled off with such uncurrent pay." },
    { r = {"SEBASTIAN"}, t = "But were my worth, as is my conscience, firm," },
    { r = {"SEBASTIAN"}, t = "You should find better dealing. What’s to do?" },
    { r = {"SEBASTIAN"}, t = "Shall we go see the relics of this town?" },
    { r = {"ANTONIO"}, t = "Tomorrow, sir; best first go see your lodging." },
    { r = {"SEBASTIAN"}, t = "I am not weary, and ’tis long to night;" },
    { r = {"SEBASTIAN"}, t = "I pray you, let us satisfy our eyes" },
    { r = {"SEBASTIAN"}, t = "With the memorials and the things of fame" },
    { r = {"SEBASTIAN"}, t = "That do renown this city." },
    { r = {"ANTONIO"}, t = "Would you’d pardon me." },
    { r = {"ANTONIO"}, t = "I do not without danger walk these streets." },
    { r = {"ANTONIO"}, t = "Once in a sea-fight, ’gainst the Count his galleys," },
    { r = {"ANTONIO"}, t = "I did some service, of such note indeed," },
    { r = {"ANTONIO"}, t = "That were I ta’en here, it would scarce be answer’d." },
    { r = {"SEBASTIAN"}, t = "Belike you slew great number of his people." },
    { r = {"ANTONIO"}, t = "Th’ offence is not of such a bloody nature," },
    { r = {"ANTONIO"}, t = "Albeit the quality of the time and quarrel" },
    { r = {"ANTONIO"}, t = "Might well have given us bloody argument." },
    { r = {"ANTONIO"}, t = "It might have since been answered in repaying" },
    { r = {"ANTONIO"}, t = "What we took from them, which for traffic’s sake," },
    { r = {"ANTONIO"}, t = "Most of our city did. Only myself stood out," },
    { r = {"ANTONIO"}, t = "For which, if I be lapsed in this place," },
    { r = {"ANTONIO"}, t = "I shall pay dear." },
    { r = {"SEBASTIAN"}, t = "Do not then walk too open." },
    { r = {"ANTONIO"}, t = "It doth not fit me. Hold, sir, here’s my purse." },
    { r = {"ANTONIO"}, t = "In the south suburbs, at the Elephant," },
    { r = {"ANTONIO"}, t = "Is best to lodge. I will bespeak our diet" },
    { r = {"ANTONIO"}, t = "Whiles you beguile the time and feed your knowledge" },
    { r = {"ANTONIO"}, t = "With viewing of the town. There shall you have me." },
    { r = {"SEBASTIAN"}, t = "Why I your purse?" },
    { r = {"ANTONIO"}, t = "Haply your eye shall light upon some toy" },
    { r = {"ANTONIO"}, t = "You have desire to purchase; and your store," },
    { r = {"ANTONIO"}, t = "I think, is not for idle markets, sir." },
    { r = {"SEBASTIAN"}, t = "I’ll be your purse-bearer, and leave you for an hour." },
    { r = {"ANTONIO"}, t = "To th’ Elephant." },
    { r = {"SEBASTIAN"}, t = "I do remember." },
    { d = "Exeunt" },
    { d = "Act 3, Scene 4. Olivia’s garden.", h = true },
    { d = "Enter Olivia and Maria" },
    { r = {"OLIVIA"}, t = "I have sent after him. He says he’ll come;" },
    { r = {"OLIVIA"}, t = "How shall I feast him? What bestow of him?" },
    { r = {"OLIVIA"}, t = "For youth is bought more oft than begg’d or borrow’d." },
    { r = {"OLIVIA"}, t = "I speak too loud.—" },
    { r = {"OLIVIA"}, t = "Where’s Malvolio?—He is sad and civil," },
    { r = {"OLIVIA"}, t = "And suits well for a servant with my fortunes;" },
    { r = {"OLIVIA"}, t = "Where is Malvolio?" },
    { r = {"MARIA"}, t = "He’s coming, madam:" },
    { r = {"MARIA"}, t = "But in very strange manner. He is sure possessed, madam." },
    { r = {"OLIVIA"}, t = "Why, what’s the matter? Does he rave?" },
    { r = {"MARIA"}, t = "No, madam, he does nothing but smile: your ladyship were best to have some guard about you if he come, for sure the man is tainted in ’s wits." },
    { r = {"OLIVIA"}, t = "Go call him hither. I’m as mad as he," },
    { r = {"OLIVIA"}, t = "If sad and merry madness equal be." },
    { d = "Enter Malvolio" },
    { r = {"OLIVIA"}, t = "How now, Malvolio?" },
    { r = {"MALVOLIO"}, t = "Sweet lady, ho, ho!" },
    { r = {"OLIVIA"}, t = "Smil’st thou? I sent for thee upon a sad occasion." },
    { r = {"MALVOLIO"}, t = "Sad, lady?" },
    { r = {"MALVOLIO"}, t = "I could be sad: this does make some obstruction in the blood, this cross-gartering." },
    { r = {"MALVOLIO"}, t = "But what of that?" },
    { r = {"MALVOLIO"}, t = "If it please the eye of one, it is with me as the very true sonnet is: ‘Please one and please all.’" },
    { r = {"OLIVIA"}, t = "Why, how dost thou, man? What is the matter with thee?" },
    { r = {"MALVOLIO"}, t = "Not black in my mind, though yellow in my legs." },
    { r = {"MALVOLIO"}, t = "It did come to his hands, and commands shall be executed." },
    { r = {"MALVOLIO"}, t = "I think we do know the sweet Roman hand." },
    { r = {"OLIVIA"}, t = "Wilt thou go to bed, Malvolio?" },
    { r = {"MALVOLIO"}, t = "To bed? Ay, sweetheart, and I’ll come to thee." },
    { r = {"OLIVIA"}, t = "God comfort thee! Why dost thou smile so, and kiss thy hand so oft?" },
    { r = {"MARIA"}, t = "How do you, Malvolio?" },
    { r = {"MALVOLIO"}, t = "At your request? Yes, nightingales answer daws!" },
    { r = {"MARIA"}, t = "Why appear you with this ridiculous boldness before my lady?" },
    { r = {"MALVOLIO"}, t = "‘Be not afraid of greatness.’ ’Twas well writ." },
    { r = {"OLIVIA"}, t = "What mean’st thou by that, Malvolio?" },
    { r = {"MALVOLIO"}, t = "‘Some are born great’" },
    { r = {"OLIVIA"}, t = "Ha?" },
    { r = {"MALVOLIO"}, t = "‘Some achieve greatness’" },
    { r = {"OLIVIA"}, t = "What say’st thou?" },
    { r = {"MALVOLIO"}, t = "‘And some have greatness thrust upon them.’" },
    { r = {"OLIVIA"}, t = "Heaven restore thee!" },
    { r = {"MALVOLIO"}, t = "‘Remember who commended thy yellow stockings’" },
    { r = {"OLIVIA"}, t = "Thy yellow stockings?" },
    { r = {"MALVOLIO"}, t = "‘And wished to see thee cross-gartered.’" },
    { r = {"OLIVIA"}, t = "Cross-gartered?" },
    { r = {"MALVOLIO"}, t = "‘Go to: thou art made, if thou desir’st to be so:’" },
    { r = {"OLIVIA"}, t = "Am I made?" },
    { r = {"MALVOLIO"}, t = "‘If not, let me see thee a servant still.’" },
    { r = {"OLIVIA"}, t = "Why, this is very midsummer madness." },
    { d = "Enter Servant" },
    { r = {"SERVANT"}, t = "Madam, the young gentleman of the Count Orsino’s is returned; I could hardly entreat him back." },
    { r = {"SERVANT"}, t = "He attends your ladyship’s pleasure." },
    { r = {"OLIVIA"}, t = "I’ll come to him." },
    { d = "Exit Servant" },
    { r = {"OLIVIA"}, t = "Good Maria, let this fellow be looked to." },
    { r = {"OLIVIA"}, t = "Where’s my cousin Toby?" },
    { r = {"OLIVIA"}, t = "Let some of my people have a special care of him; I would not have him miscarry for the half of my dowry." },
    { d = "Exeunt Olivia and Maria" },
    { r = {"MALVOLIO"}, t = "O ho, do you come near me now?" },
    { r = {"MALVOLIO"}, t = "No worse man than Sir Toby to look to me." },
    { r = {"MALVOLIO"}, t = "This concurs directly with the letter: she sends him on purpose, that I may appear stubborn to him; for she incites me to that in the letter." },
    { r = {"MALVOLIO"}, t = "‘Cast thy humble slough,’ says she; ‘be opposite with a kinsman, surly with servants, let thy tongue tang with arguments of state, put thyself into the trick of singularity,’ and consequently, sets down the manner how:" },
    { r = {"MALVOLIO"}, t = "as, a sad face, a reverend carriage, a slow tongue, in the habit of some sir of note, and so forth." },
    { r = {"MALVOLIO"}, t = "I have limed her, but it is Jove’s doing, and Jove make me thankful!" },
    { r = {"MALVOLIO"}, t = "And when she went away now, ‘Let this fellow be looked to;’ ‘Fellow!’ not" },
    { r = {"MALVOLIO"}, t = "‘Malvolio’, nor after my degree, but ‘fellow’." },
    { r = {"MALVOLIO"}, t = "Why, everything adheres together, that no dram of a scruple, no scruple of a scruple, no obstacle, no incredulous or unsafe circumstance." },
    { r = {"MALVOLIO"}, t = "What can be said?" },
    { r = {"MALVOLIO"}, t = "Nothing that can be can come between me and the full prospect of my hopes." },
    { r = {"MALVOLIO"}, t = "Well, Jove, not I, is the doer of this, and he is to be thanked." },
    { d = "Enter Sir Toby, Fabian and Maria" },
    { r = {"SIR TOBY BELCH"}, t = "Which way is he, in the name of sanctity?" },
    { r = {"SIR TOBY BELCH"}, t = "If all the devils of hell be drawn in little, and Legion himself possessed him, yet I’ll speak to him." },
    { r = {"FABIAN"}, t = "Here he is, here he is. How is’t with you, sir? How is’t with you, man?" },
    { r = {"MALVOLIO"}, t = "Go off, I discard you. Let me enjoy my private. Go off." },
    { r = {"MARIA"}, t = "Lo, how hollow the fiend speaks within him!" },
    { r = {"MARIA"}, t = "Did not I tell you?" },
    { r = {"MARIA"}, t = "Sir Toby, my lady prays you to have a care of him." },
    { r = {"MALVOLIO"}, t = "Ah, ha! does she so?" },
    { r = {"SIR TOBY BELCH"}, t = "Go to, go to; peace, peace, we must deal gently with him. Let me alone." },
    { r = {"SIR TOBY BELCH"}, t = "How do you, Malvolio? How is’t with you? What, man! defy the devil!" },
    { r = {"SIR TOBY BELCH"}, t = "Consider, he’s an enemy to mankind." },
    { r = {"MALVOLIO"}, t = "Do you know what you say?" },
    { r = {"MARIA"}, t = "La you, an you speak ill of the devil, how he takes it at heart!" },
    { r = {"MARIA"}, t = "Pray God he be not bewitched." },
    { r = {"FABIAN"}, t = "Carry his water to th’ wise woman." },
    { r = {"MARIA"}, t = "Marry, and it shall be done tomorrow morning, if I live." },
    { r = {"MARIA"}, t = "My lady would not lose him for more than I’ll say." },
    { r = {"MALVOLIO"}, t = "How now, mistress!" },
    { r = {"MARIA"}, t = "O Lord!" },
    { r = {"SIR TOBY BELCH"}, t = "Prithee hold thy peace, this is not the way." },
    { r = {"SIR TOBY BELCH"}, t = "Do you not see you move him?" },
    { r = {"SIR TOBY BELCH"}, t = "Let me alone with him." },
    { r = {"FABIAN"}, t = "No way but gentleness, gently, gently." },
    { r = {"FABIAN"}, t = "The fiend is rough, and will not be roughly used." },
    { r = {"SIR TOBY BELCH"}, t = "Why, how now, my bawcock? How dost thou, chuck?" },
    { r = {"MALVOLIO"}, t = "Sir!" },
    { r = {"SIR TOBY BELCH"}, t = "Ay, biddy, come with me." },
    { r = {"SIR TOBY BELCH"}, t = "What, man, ’tis not for gravity to play at cherry-pit with Satan." },
    { r = {"SIR TOBY BELCH"}, t = "Hang him, foul collier!" },
    { r = {"MARIA"}, t = "Get him to say his prayers, good Sir Toby, get him to pray." },
    { r = {"MALVOLIO"}, t = "My prayers, minx?" },
    { r = {"MARIA"}, t = "No, I warrant you, he will not hear of godliness." },
    { r = {"MALVOLIO"}, t = "Go, hang yourselves all!" },
    { r = {"MALVOLIO"}, t = "You are idle, shallow things." },
    { r = {"MALVOLIO"}, t = "I am not of your element." },
    { r = {"MALVOLIO"}, t = "You shall know more hereafter." },
    { d = "Exit" },
    { r = {"SIR TOBY BELCH"}, t = "Is’t possible?" },
    { r = {"FABIAN"}, t = "If this were played upon a stage now, I could condemn it as an improbable fiction." },
    { r = {"SIR TOBY BELCH"}, t = "His very genius hath taken the infection of the device, man." },
    { r = {"MARIA"}, t = "Nay, pursue him now, lest the device take air and taint." },
    { r = {"FABIAN"}, t = "Why, we shall make him mad indeed." },
    { r = {"MARIA"}, t = "The house will be the quieter." },
    { r = {"SIR TOBY BELCH"}, t = "Come, we’ll have him in a dark room and bound." },
    { r = {"SIR TOBY BELCH"}, t = "My niece is already in the belief that he’s mad." },
    { r = {"SIR TOBY BELCH"}, t = "We may carry it thus for our pleasure, and his penance, till our very pastime, tired out of breath, prompt us to have mercy on him, at which time we will bring the device to the bar, and crown thee for a finder of madmen." },
    { r = {"SIR TOBY BELCH"}, t = "But see, but see!" },
    { d = "Enter Sir Andrew" },
    { r = {"FABIAN"}, t = "More matter for a May morning." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Here’s the challenge, read it." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I warrant there’s vinegar and pepper in’t." },
    { r = {"FABIAN"}, t = "Is’t so saucy?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Ay, is’t, I warrant him. Do but read." },
    { r = {"SIR TOBY BELCH"}, t = "Give me." },
    { r = {"SIR TOBY BELCH"}, t = "Youth, whatsoever thou art, thou art but a scurvy fellow.", d = "Reads" },
    { r = {"FABIAN"}, t = "Good, and valiant." },
    { r = {"SIR TOBY BELCH"}, t = "Wonder not, nor admire not in thy mind, why I do call thee so, for I will show thee no reason for’t." },
    { r = {"FABIAN"}, t = "A good note, that keeps you from the blow of the law." },
    { r = {"SIR TOBY BELCH"}, t = "Thou comest to the Lady Olivia, and in my sight she uses thee kindly: but thou liest in thy throat; that is not the matter I challenge thee for." },
    { r = {"FABIAN"}, t = "Very brief, and to exceeding good sense—less." },
    { r = {"SIR TOBY BELCH"}, t = "I will waylay thee going home; where if it be thy chance to kill me" },
    { r = {"FABIAN"}, t = "Good." },
    { r = {"SIR TOBY BELCH"}, t = "Thou kill’st me like a rogue and a villain." },
    { r = {"FABIAN"}, t = "Still you keep o’ th’ windy side of the law. Good." },
    { r = {"SIR TOBY BELCH"}, t = "Fare thee well, and God have mercy upon one of our souls!" },
    { r = {"SIR TOBY BELCH"}, t = "He may have mercy upon mine, but my hope is better, and so look to thyself." },
    { r = {"SIR TOBY BELCH"}, t = "Thy friend, as thou usest him, and thy sworn enemy," },
    { r = {"SIR TOBY BELCH"}, t = "Andrew Aguecheek." },
    { r = {"SIR TOBY BELCH"}, t = "If this letter move him not, his legs cannot. I’ll give’t him." },
    { r = {"MARIA"}, t = "You may have very fit occasion for’t." },
    { r = {"MARIA"}, t = "He is now in some commerce with my lady, and will by and by depart." },
    { r = {"SIR TOBY BELCH"}, t = "Go, Sir Andrew." },
    { r = {"SIR TOBY BELCH"}, t = "Scout me for him at the corner of the orchard, like a bum-baily." },
    { r = {"SIR TOBY BELCH"}, t = "So soon as ever thou seest him, draw, and as thou draw’st, swear horrible, for it comes to pass oft that a terrible oath, with a swaggering accent sharply twanged off, gives manhood more approbation than ever proof itself would have earned him." },
    { r = {"SIR TOBY BELCH"}, t = "Away." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Nay, let me alone for swearing." },
    { d = "Exit" },
    { r = {"SIR TOBY BELCH"}, t = "Now will not I deliver his letter, for the behaviour of the young gentleman gives him out to be of good capacity and breeding; his employment between his lord and my niece confirms no less." },
    { r = {"SIR TOBY BELCH"}, t = "Therefore this letter, being so excellently ignorant, will breed no terror in the youth." },
    { r = {"SIR TOBY BELCH"}, t = "He will find it comes from a clodpole." },
    { r = {"SIR TOBY BELCH"}, t = "But, sir, I will deliver his challenge by word of mouth, set upon Aguecheek notable report of valour, and drive the gentleman (as I know his youth will aptly receive it) into a most hideous opinion of his rage, skill, fury, and impetuosity." },
    { r = {"SIR TOBY BELCH"}, t = "This will so fright them both that they will kill one another by the look, like cockatrices." },
    { d = "Enter Olivia and Viola" },
    { r = {"FABIAN"}, t = "Here he comes with your niece; give them way till he take leave, and presently after him." },
    { r = {"SIR TOBY BELCH"}, t = "I will meditate the while upon some horrid message for a challenge." },
    { d = "Exeunt Sir Toby, Fabian and Maria" },
    { r = {"OLIVIA"}, t = "I have said too much unto a heart of stone," },
    { r = {"OLIVIA"}, t = "And laid mine honour too unchary on’t:" },
    { r = {"OLIVIA"}, t = "There’s something in me that reproves my fault:" },
    { r = {"OLIVIA"}, t = "But such a headstrong potent fault it is," },
    { r = {"OLIVIA"}, t = "That it but mocks reproof." },
    { r = {"VIOLA"}, t = "With the same ’haviour that your passion bears" },
    { r = {"VIOLA"}, t = "Goes on my master’s griefs." },
    { r = {"OLIVIA"}, t = "Here, wear this jewel for me, ’tis my picture." },
    { r = {"OLIVIA"}, t = "Refuse it not, it hath no tongue to vex you." },
    { r = {"OLIVIA"}, t = "And I beseech you come again tomorrow." },
    { r = {"OLIVIA"}, t = "What shall you ask of me that I’ll deny," },
    { r = {"OLIVIA"}, t = "That honour sav’d, may upon asking give?" },
    { r = {"VIOLA"}, t = "Nothing but this, your true love for my master." },
    { r = {"OLIVIA"}, t = "How with mine honour may I give him that" },
    { r = {"OLIVIA"}, t = "Which I have given to you?" },
    { r = {"VIOLA"}, t = "I will acquit you." },
    { r = {"OLIVIA"}, t = "Well, come again tomorrow. Fare thee well;" },
    { r = {"OLIVIA"}, t = "A fiend like thee might bear my soul to hell." },
    { d = "Exit" },
    { d = "Enter Sir Toby and Fabian" },
    { r = {"SIR TOBY BELCH"}, t = "Gentleman, God save thee." },
    { r = {"VIOLA"}, t = "And you, sir." },
    { r = {"SIR TOBY BELCH"}, t = "That defence thou hast, betake thee to’t." },
    { r = {"SIR TOBY BELCH"}, t = "Of what nature the wrongs are thou hast done him, I know not, but thy intercepter, full of despite, bloody as the hunter, attends thee at the orchard end." },
    { r = {"SIR TOBY BELCH"}, t = "Dismount thy tuck, be yare in thy preparation, for thy assailant is quick, skilful, and deadly." },
    { r = {"VIOLA"}, t = "You mistake, sir; I am sure no man hath any quarrel to me." },
    { r = {"VIOLA"}, t = "My remembrance is very free and clear from any image of offence done to any man." },
    { r = {"SIR TOBY BELCH"}, t = "You’ll find it otherwise, I assure you." },
    { r = {"SIR TOBY BELCH"}, t = "Therefore, if you hold your life at any price, betake you to your guard, for your opposite hath in him what youth, strength, skill, and wrath, can furnish man withal." },
    { r = {"VIOLA"}, t = "I pray you, sir, what is he?" },
    { r = {"SIR TOBY BELCH"}, t = "He is knight, dubbed with unhatched rapier, and on carpet consideration, but he is a devil in private brawl." },
    { r = {"SIR TOBY BELCH"}, t = "Souls and bodies hath he divorced three, and his incensement at this moment is so implacable that satisfaction can be none but by pangs of death and sepulchre." },
    { r = {"SIR TOBY BELCH"}, t = "Hob, nob is his word; give’t or take’t." },
    { r = {"VIOLA"}, t = "I will return again into the house and desire some conduct of the lady." },
    { r = {"VIOLA"}, t = "I am no fighter." },
    { r = {"VIOLA"}, t = "I have heard of some kind of men that put quarrels purposely on others to taste their valour: belike this is a man of that quirk." },
    { r = {"SIR TOBY BELCH"}, t = "Sir, no." },
    { r = {"SIR TOBY BELCH"}, t = "His indignation derives itself out of a very competent injury; therefore, get you on and give him his desire." },
    { r = {"SIR TOBY BELCH"}, t = "Back you shall not to the house, unless you undertake that with me which with as much safety you might answer him." },
    { r = {"SIR TOBY BELCH"}, t = "Therefore on, or strip your sword stark naked, for meddle you must, that’s certain, or forswear to wear iron about you." },
    { r = {"VIOLA"}, t = "This is as uncivil as strange." },
    { r = {"VIOLA"}, t = "I beseech you, do me this courteous office, as to know of the knight what my offence to him is." },
    { r = {"VIOLA"}, t = "It is something of my negligence, nothing of my purpose." },
    { r = {"SIR TOBY BELCH"}, t = "I will do so." },
    { r = {"SIR TOBY BELCH"}, t = "Signior Fabian, stay you by this gentleman till my return." },
    { d = "Exit Sir Toby" },
    { r = {"VIOLA"}, t = "Pray you, sir, do you know of this matter?" },
    { r = {"FABIAN"}, t = "I know the knight is incensed against you, even to a mortal arbitrement, but nothing of the circumstance more." },
    { r = {"VIOLA"}, t = "I beseech you, what manner of man is he?" },
    { r = {"FABIAN"}, t = "Nothing of that wonderful promise, to read him by his form, as you are like to find him in the proof of his valour." },
    { r = {"FABIAN"}, t = "He is indeed, sir, the most skilful, bloody, and fatal opposite that you could possibly have found in any part of Illyria." },
    { r = {"FABIAN"}, t = "Will you walk towards him?" },
    { r = {"FABIAN"}, t = "I will make your peace with him if I can." },
    { r = {"VIOLA"}, t = "I shall be much bound to you for’t." },
    { r = {"VIOLA"}, t = "I am one that had rather go with sir priest than sir knight: I care not who knows so much of my mettle." },
    { d = "Exeunt" },
    { d = "Enter Sir Toby and Sir Andrew" },
    { r = {"SIR TOBY BELCH"}, t = "Why, man, he’s a very devil." },
    { r = {"SIR TOBY BELCH"}, t = "I have not seen such a firago." },
    { r = {"SIR TOBY BELCH"}, t = "I had a pass with him, rapier, scabbard, and all, and he gives me the stuck-in with such a mortal motion that it is inevitable; and on the answer, he pays you as surely as your feet hits the ground they step on." },
    { r = {"SIR TOBY BELCH"}, t = "They say he has been fencer to the Sophy." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Pox on’t, I’ll not meddle with him." },
    { r = {"SIR TOBY BELCH"}, t = "Ay, but he will not now be pacified: Fabian can scarce hold him yonder." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Plague on’t, an I thought he had been valiant, and so cunning in fence, I’d have seen him damned ere I’d have challenged him." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Let him let the matter slip, and I’ll give him my horse, grey Capilet." },
    { r = {"SIR TOBY BELCH"}, t = "I’ll make the motion." },
    { r = {"SIR TOBY BELCH"}, t = "Stand here, make a good show on’t." },
    { r = {"SIR TOBY BELCH"}, t = "This shall end without the perdition of souls." },
    { r = {"SIR TOBY BELCH"}, t = "Marry, I’ll ride your horse as well as I ride you.", d = "Aside" },
    { d = "Enter Fabian and Viola" },
    { r = {"SIR TOBY BELCH"}, t = "I have his horse to take up the quarrel.", d = "To Fabian" },
    { r = {"SIR TOBY BELCH"}, t = "I have persuaded him the youth’s a devil." },
    { r = {"FABIAN"}, t = "He is as horribly conceited of him, and pants and looks pale, as if a bear were at his heels." },
    { r = {"SIR TOBY BELCH"}, t = "There’s no remedy, sir, he will fight with you for’s oath sake." },
    { r = {"SIR TOBY BELCH"}, t = "Marry, he hath better bethought him of his quarrel, and he finds that now scarce to be worth talking of." },
    { r = {"SIR TOBY BELCH"}, t = "Therefore, draw for the supportance of his vow; he protests he will not hurt you." },
    { r = {"VIOLA"}, t = "Pray God defend me!", d = "Aside" },
    { r = {"VIOLA"}, t = "A little thing would make me tell them how much I lack of a man." },
    { r = {"FABIAN"}, t = "Give ground if you see him furious." },
    { r = {"SIR TOBY BELCH"}, t = "Come, Sir Andrew, there’s no remedy, the gentleman will for his honour’s sake have one bout with you." },
    { r = {"SIR TOBY BELCH"}, t = "He cannot by the duello avoid it; but he has promised me, as he is a gentleman and a soldier, he will not hurt you." },
    { r = {"SIR TOBY BELCH"}, t = "Come on: to’t." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Pray God he keep his oath!", d = "Draws" },
    { d = "Enter Antonio" },
    { r = {"VIOLA"}, t = "I do assure you ’tis against my will.", d = "Draws" },
    { r = {"ANTONIO"}, t = "Put up your sword. If this young gentleman" },
    { r = {"ANTONIO"}, t = "Have done offence, I take the fault on me." },
    { r = {"ANTONIO"}, t = "If you offend him, I for him defy you." },
    { r = {"SIR TOBY BELCH"}, t = "You, sir? Why, what are you?" },
    { r = {"ANTONIO"}, t = "One, sir, that for his love dares yet do more", d = "Draws" },
    { r = {"ANTONIO"}, t = "Than you have heard him brag to you he will." },
    { r = {"SIR TOBY BELCH"}, t = "Nay, if you be an undertaker, I am for you.", d = "Draws" },
    { d = "Enter Officers" },
    { r = {"FABIAN"}, t = "O good Sir Toby, hold! Here come the officers." },
    { r = {"SIR TOBY BELCH"}, t = "I’ll be with you anon.", d = "To Antonio" },
    { r = {"VIOLA"}, t = "Pray, sir, put your sword up, if you please.", d = "To Sir Andrew" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Marry, will I, sir; and for that I promised you, I’ll be as good as my word." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "He will bear you easily, and reins well." },
    { r = {"FIRST OFFICER"}, t = "This is the man; do thy office." },
    { r = {"SECOND OFFICER"}, t = "Antonio, I arrest thee at the suit" },
    { r = {"SECOND OFFICER"}, t = "Of Count Orsino." },
    { r = {"ANTONIO"}, t = "You do mistake me, sir." },
    { r = {"FIRST OFFICER"}, t = "No, sir, no jot. I know your favour well," },
    { r = {"FIRST OFFICER"}, t = "Though now you have no sea-cap on your head.—" },
    { r = {"FIRST OFFICER"}, t = "Take him away, he knows I know him well." },
    { r = {"ANTONIO"}, t = "I must obey. This comes with seeking you;" },
    { r = {"ANTONIO"}, t = "But there’s no remedy, I shall answer it." },
    { r = {"ANTONIO"}, t = "What will you do? Now my necessity" },
    { r = {"ANTONIO"}, t = "Makes me to ask you for my purse. It grieves me" },
    { r = {"ANTONIO"}, t = "Much more for what I cannot do for you," },
    { r = {"ANTONIO"}, t = "Than what befalls myself. You stand amaz’d," },
    { r = {"ANTONIO"}, t = "But be of comfort." },
    { r = {"SECOND OFFICER"}, t = "Come, sir, away." },
    { r = {"ANTONIO"}, t = "I must entreat of you some of that money." },
    { r = {"VIOLA"}, t = "What money, sir?" },
    { r = {"VIOLA"}, t = "For the fair kindness you have show’d me here," },
    { r = {"VIOLA"}, t = "And part being prompted by your present trouble," },
    { r = {"VIOLA"}, t = "Out of my lean and low ability" },
    { r = {"VIOLA"}, t = "I’ll lend you something. My having is not much;" },
    { r = {"VIOLA"}, t = "I’ll make division of my present with you." },
    { r = {"VIOLA"}, t = "Hold, there’s half my coffer." },
    { r = {"ANTONIO"}, t = "Will you deny me now?" },
    { r = {"ANTONIO"}, t = "Is’t possible that my deserts to you" },
    { r = {"ANTONIO"}, t = "Can lack persuasion? Do not tempt my misery," },
    { r = {"ANTONIO"}, t = "Lest that it make me so unsound a man" },
    { r = {"ANTONIO"}, t = "As to upbraid you with those kindnesses" },
    { r = {"ANTONIO"}, t = "That I have done for you." },
    { r = {"VIOLA"}, t = "I know of none," },
    { r = {"VIOLA"}, t = "Nor know I you by voice or any feature." },
    { r = {"VIOLA"}, t = "I hate ingratitude more in a man" },
    { r = {"VIOLA"}, t = "Than lying, vainness, babbling, drunkenness," },
    { r = {"VIOLA"}, t = "Or any taint of vice whose strong corruption" },
    { r = {"VIOLA"}, t = "Inhabits our frail blood." },
    { r = {"ANTONIO"}, t = "O heavens themselves!" },
    { r = {"SECOND OFFICER"}, t = "Come, sir, I pray you go." },
    { r = {"ANTONIO"}, t = "Let me speak a little. This youth that you see here" },
    { r = {"ANTONIO"}, t = "I snatch’d one half out of the jaws of death," },
    { r = {"ANTONIO"}, t = "Reliev’d him with such sanctity of love;" },
    { r = {"ANTONIO"}, t = "And to his image, which methought did promise" },
    { r = {"ANTONIO"}, t = "Most venerable worth, did I devotion." },
    { r = {"FIRST OFFICER"}, t = "What’s that to us? The time goes by. Away!" },
    { r = {"ANTONIO"}, t = "But O how vile an idol proves this god!" },
    { r = {"ANTONIO"}, t = "Thou hast, Sebastian, done good feature shame." },
    { r = {"ANTONIO"}, t = "In nature there’s no blemish but the mind;" },
    { r = {"ANTONIO"}, t = "None can be call’d deform’d but the unkind." },
    { r = {"ANTONIO"}, t = "Virtue is beauty, but the beauteous evil" },
    { r = {"ANTONIO"}, t = "Are empty trunks, o’erflourished by the devil." },
    { r = {"FIRST OFFICER"}, t = "The man grows mad, away with him. Come, come, sir." },
    { r = {"ANTONIO"}, t = "Lead me on." },
    { d = "Exeunt Officers with Antonio" },
    { r = {"VIOLA"}, t = "Methinks his words do from such passion fly" },
    { r = {"VIOLA"}, t = "That he believes himself; so do not I." },
    { r = {"VIOLA"}, t = "Prove true, imagination, O prove true," },
    { r = {"VIOLA"}, t = "That I, dear brother, be now ta’en for you!" },
    { r = {"SIR TOBY BELCH"}, t = "Come hither, knight; come hither, Fabian." },
    { r = {"SIR TOBY BELCH"}, t = "We’ll whisper o’er a couplet or two of most sage saws." },
    { r = {"VIOLA"}, t = "He nam’d Sebastian. I my brother know" },
    { r = {"VIOLA"}, t = "Yet living in my glass; even such and so" },
    { r = {"VIOLA"}, t = "In favour was my brother, and he went" },
    { r = {"VIOLA"}, t = "Still in this fashion, colour, ornament," },
    { r = {"VIOLA"}, t = "For him I imitate. O if it prove," },
    { r = {"VIOLA"}, t = "Tempests are kind, and salt waves fresh in love!" },
    { d = "Exit" },
    { r = {"SIR TOBY BELCH"}, t = "A very dishonest paltry boy, and more a coward than a hare." },
    { r = {"SIR TOBY BELCH"}, t = "His dishonesty appears in leaving his friend here in necessity, and denying him; and for his cowardship, ask Fabian." },
    { r = {"FABIAN"}, t = "A coward, a most devout coward, religious in it." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Slid, I’ll after him again and beat him." },
    { r = {"SIR TOBY BELCH"}, t = "Do, cuff him soundly, but never draw thy sword." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "And I do not" },
    { d = "Exit" },
    { r = {"FABIAN"}, t = "Come, let’s see the event." },
    { r = {"SIR TOBY BELCH"}, t = "I dare lay any money ’twill be nothing yet." },
    { d = "Exeunt" },
    { d = "Act 4, Scene 1. The Street before Olivia’s House.", h = true },
    { d = "Enter Sebastian and Clown" },
    { r = {"CLOWN"}, t = "Will you make me believe that I am not sent for you?" },
    { r = {"SEBASTIAN"}, t = "Go to, go to, thou art a foolish fellow." },
    { r = {"SEBASTIAN"}, t = "Let me be clear of thee." },
    { r = {"CLOWN"}, t = "Well held out, i’ faith!" },
    { r = {"CLOWN"}, t = "No, I do not know you, nor I am not sent to you by my lady, to bid you come speak with her; nor your name is not Master Cesario; nor this is not my nose neither." },
    { r = {"CLOWN"}, t = "Nothing that is so, is so." },
    { r = {"SEBASTIAN"}, t = "I prithee vent thy folly somewhere else," },
    { r = {"SEBASTIAN"}, t = "Thou know’st not me." },
    { r = {"CLOWN"}, t = "Vent my folly!" },
    { r = {"CLOWN"}, t = "He has heard that word of some great man, and now applies it to a fool." },
    { r = {"CLOWN"}, t = "Vent my folly!" },
    { r = {"CLOWN"}, t = "I am afraid this great lubber, the world, will prove a cockney." },
    { r = {"CLOWN"}, t = "I prithee now, ungird thy strangeness, and tell me what I shall vent to my lady." },
    { r = {"CLOWN"}, t = "Shall I vent to her that thou art coming?" },
    { r = {"SEBASTIAN"}, t = "I prithee, foolish Greek, depart from me." },
    { r = {"SEBASTIAN"}, t = "There’s money for thee; if you tarry longer" },
    { r = {"SEBASTIAN"}, t = "I shall give worse payment." },
    { r = {"CLOWN"}, t = "By my troth, thou hast an open hand." },
    { r = {"CLOWN"}, t = "These wise men that give fools money get themselves a good report—after fourteen years’ purchase." },
    { d = "Enter Sir Andrew, Sir Toby and Fabian" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Now sir, have I met you again? There’s for you." },
    { d = "Striking Sebastian" },
    { r = {"SEBASTIAN"}, t = "Why, there’s for thee, and there, and there." },
    { r = {"SEBASTIAN"}, t = "Are all the people mad?" },
    { d = "Beating Sir Andrew" },
    { r = {"SIR TOBY BELCH"}, t = "Hold, sir, or I’ll throw your dagger o’er the house." },
    { r = {"CLOWN"}, t = "This will I tell my lady straight." },
    { r = {"CLOWN"}, t = "I would not be in some of your coats for twopence." },
    { d = "Exit Clown" },
    { r = {"SIR TOBY BELCH"}, t = "Come on, sir, hold!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Nay, let him alone, I’ll go another way to work with him." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I’ll have an action of battery against him, if there be any law in Illyria." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Though I struck him first, yet it’s no matter for that." },
    { r = {"SEBASTIAN"}, t = "Let go thy hand!" },
    { r = {"SIR TOBY BELCH"}, t = "Come, sir, I will not let you go." },
    { r = {"SIR TOBY BELCH"}, t = "Come, my young soldier, put up your iron: you are well fleshed." },
    { r = {"SIR TOBY BELCH"}, t = "Come on." },
    { r = {"SEBASTIAN"}, t = "I will be free from thee. What wouldst thou now?" },
    { r = {"SEBASTIAN"}, t = "If thou dar’st tempt me further, draw thy sword." },
    { d = "Draws" },
    { r = {"SIR TOBY BELCH"}, t = "What, what?" },
    { r = {"SIR TOBY BELCH"}, t = "Nay, then, I must have an ounce or two of this malapert blood from you." },
    { d = "Draws" },
    { d = "Enter Olivia" },
    { r = {"OLIVIA"}, t = "Hold, Toby! On thy life I charge thee hold!" },
    { r = {"SIR TOBY BELCH"}, t = "Madam." },
    { r = {"OLIVIA"}, t = "Will it be ever thus? Ungracious wretch," },
    { r = {"OLIVIA"}, t = "Fit for the mountains and the barbarous caves," },
    { r = {"OLIVIA"}, t = "Where manners ne’er were preach’d! Out of my sight!" },
    { r = {"OLIVIA"}, t = "Be not offended, dear Cesario." },
    { r = {"OLIVIA"}, t = "Rudesby, be gone!" },
    { d = "Exeunt Sir Toby, Sir Andrew and Fabian" },
    { r = {"OLIVIA"}, t = "I prithee, gentle friend," },
    { r = {"OLIVIA"}, t = "Let thy fair wisdom, not thy passion, sway" },
    { r = {"OLIVIA"}, t = "In this uncivil and unjust extent" },
    { r = {"OLIVIA"}, t = "Against thy peace. Go with me to my house," },
    { r = {"OLIVIA"}, t = "And hear thou there how many fruitless pranks" },
    { r = {"OLIVIA"}, t = "This ruffian hath botch’d up, that thou thereby" },
    { r = {"OLIVIA"}, t = "Mayst smile at this. Thou shalt not choose but go." },
    { r = {"OLIVIA"}, t = "Do not deny. Beshrew his soul for me," },
    { r = {"OLIVIA"}, t = "He started one poor heart of mine, in thee." },
    { r = {"SEBASTIAN"}, t = "What relish is in this? How runs the stream?" },
    { r = {"SEBASTIAN"}, t = "Or I am mad, or else this is a dream." },
    { r = {"SEBASTIAN"}, t = "Let fancy still my sense in Lethe steep;" },
    { r = {"SEBASTIAN"}, t = "If it be thus to dream, still let me sleep!" },
    { r = {"OLIVIA"}, t = "Nay, come, I prithee. Would thou’dst be ruled by me!" },
    { r = {"SEBASTIAN"}, t = "Madam, I will." },
    { r = {"OLIVIA"}, t = "O, say so, and so be!" },
    { d = "Exeunt" },
    { d = "Act 4, Scene 2. A Room in Olivia’s House.", h = true },
    { d = "Enter Maria and Clown" },
    { r = {"MARIA"}, t = "Nay, I prithee, put on this gown and this beard; make him believe thou art Sir Topas the curate." },
    { r = {"MARIA"}, t = "Do it quickly." },
    { r = {"MARIA"}, t = "I’ll call Sir Toby the whilst." },
    { d = "Exit Maria" },
    { r = {"CLOWN"}, t = "Well, I’ll put it on, and I will dissemble myself in’t, and I would I were the first that ever dissembled in such a gown." },
    { r = {"CLOWN"}, t = "I am not tall enough to become the function well, nor lean enough to be thought a good student, but to be said, an honest man and a good housekeeper goes as fairly as to say, a careful man and a great scholar." },
    { r = {"CLOWN"}, t = "The competitors enter." },
    { d = "Enter Sir Toby and Maria" },
    { r = {"SIR TOBY BELCH"}, t = "Jove bless thee, Master Parson." },
    { r = {"CLOWN"}, t = "Bonos dies, Sir Toby: for as the old hermit of Prague, that never saw pen and ink, very wittily said to a niece of King Gorboduc, ‘That that is, is’: so I, being Master Parson, am Master Parson; for what is ‘that’ but ‘that’?" },
    { r = {"CLOWN"}, t = "and ‘is’ but ‘is’?" },
    { r = {"SIR TOBY BELCH"}, t = "To him, Sir Topas." },
    { r = {"CLOWN"}, t = "What ho, I say! Peace in this prison!" },
    { r = {"SIR TOBY BELCH"}, t = "The knave counterfeits well. A good knave." },
    { r = {"SIR TOBY BELCH"}, t = "Malvolio within." },
    { r = {"MALVOLIO"}, t = "Who calls there?" },
    { r = {"CLOWN"}, t = "Sir Topas the curate, who comes to visit Malvolio the lunatic." },
    { r = {"MALVOLIO"}, t = "Sir Topas, Sir Topas, good Sir Topas, go to my lady." },
    { r = {"CLOWN"}, t = "Out, hyperbolical fiend! how vexest thou this man?" },
    { r = {"CLOWN"}, t = "Talkest thou nothing but of ladies?" },
    { r = {"SIR TOBY BELCH"}, t = "Well said, Master Parson." },
    { r = {"MALVOLIO"}, t = "Sir Topas, never was man thus wronged." },
    { r = {"MALVOLIO"}, t = "Good Sir Topas, do not think I am mad." },
    { r = {"MALVOLIO"}, t = "They have laid me here in hideous darkness." },
    { r = {"CLOWN"}, t = "Fie, thou dishonest Satan!" },
    { r = {"CLOWN"}, t = "I call thee by the most modest terms, for I am one of those gentle ones that will use the devil himself with courtesy." },
    { r = {"CLOWN"}, t = "Say’st thou that house is dark?" },
    { r = {"MALVOLIO"}, t = "As hell, Sir Topas." },
    { r = {"CLOWN"}, t = "Why, it hath bay windows transparent as barricadoes, and the clerestories toward the south-north are as lustrous as ebony; and yet complainest thou of obstruction?" },
    { r = {"MALVOLIO"}, t = "I am not mad, Sir Topas. I say to you this house is dark." },
    { r = {"CLOWN"}, t = "Madman, thou errest." },
    { r = {"CLOWN"}, t = "I say there is no darkness but ignorance, in which thou art more puzzled than the Egyptians in their fog." },
    { r = {"MALVOLIO"}, t = "I say this house is as dark as ignorance, though ignorance were as dark as hell; and I say there was never man thus abused." },
    { r = {"MALVOLIO"}, t = "I am no more mad than you are." },
    { r = {"MALVOLIO"}, t = "Make the trial of it in any constant question." },
    { r = {"CLOWN"}, t = "What is the opinion of Pythagoras concerning wildfowl?" },
    { r = {"MALVOLIO"}, t = "That the soul of our grandam might haply inhabit a bird." },
    { r = {"CLOWN"}, t = "What think’st thou of his opinion?" },
    { r = {"MALVOLIO"}, t = "I think nobly of the soul, and no way approve his opinion." },
    { r = {"CLOWN"}, t = "Fare thee well." },
    { r = {"CLOWN"}, t = "Remain thou still in darkness." },
    { r = {"CLOWN"}, t = "Thou shalt hold the opinion of Pythagoras ere I will allow of thy wits, and fear to kill a woodcock, lest thou dispossess the soul of thy grandam." },
    { r = {"CLOWN"}, t = "Fare thee well." },
    { r = {"MALVOLIO"}, t = "Sir Topas, Sir Topas!" },
    { r = {"SIR TOBY BELCH"}, t = "My most exquisite Sir Topas!" },
    { r = {"CLOWN"}, t = "Nay, I am for all waters." },
    { r = {"MARIA"}, t = "Thou mightst have done this without thy beard and gown." },
    { r = {"MARIA"}, t = "He sees thee not." },
    { r = {"SIR TOBY BELCH"}, t = "To him in thine own voice, and bring me word how thou find’st him." },
    { r = {"SIR TOBY BELCH"}, t = "I would we were well rid of this knavery." },
    { r = {"SIR TOBY BELCH"}, t = "If he may be conveniently delivered, I would he were, for I am now so far in offence with my niece that I cannot pursue with any safety this sport to the upshot." },
    { r = {"SIR TOBY BELCH"}, t = "Come by and by to my chamber." },
    { d = "Exeunt Sir Toby and Maria" },
    { r = {"CLOWN"}, t = "Hey, Robin, jolly Robin,", d = "Singing" },
    { r = {"CLOWN"}, t = "Tell me how thy lady does." },
    { r = {"MALVOLIO"}, t = "Fool!" },
    { r = {"CLOWN"}, t = "My lady is unkind, perdy." },
    { r = {"MALVOLIO"}, t = "Fool!" },
    { r = {"CLOWN"}, t = "Alas, why is she so?" },
    { r = {"MALVOLIO"}, t = "Fool, I say!" },
    { r = {"CLOWN"}, t = "She loves another—" },
    { r = {"CLOWN"}, t = "Who calls, ha?" },
    { r = {"MALVOLIO"}, t = "Good fool, as ever thou wilt deserve well at my hand, help me to a candle, and pen, ink, and paper." },
    { r = {"MALVOLIO"}, t = "As I am a gentleman, I will live to be thankful to thee for’t." },
    { r = {"CLOWN"}, t = "Master Malvolio?" },
    { r = {"MALVOLIO"}, t = "Ay, good fool." },
    { r = {"CLOWN"}, t = "Alas, sir, how fell you besides your five wits?" },
    { r = {"MALVOLIO"}, t = "Fool, there was never man so notoriously abused." },
    { r = {"MALVOLIO"}, t = "I am as well in my wits, fool, as thou art." },
    { r = {"CLOWN"}, t = "But as well?" },
    { r = {"CLOWN"}, t = "Then you are mad indeed, if you be no better in your wits than a fool." },
    { r = {"MALVOLIO"}, t = "They have here propertied me; keep me in darkness, send ministers to me, asses, and do all they can to face me out of my wits." },
    { r = {"CLOWN"}, t = "Advise you what you say: the minister is here." },
    { r = {"CLOWN"}, t = "Malvolio, Malvolio, thy wits the heavens restore.", d = "As Sir Topas" },
    { r = {"CLOWN"}, t = "Endeavour thyself to sleep, and leave thy vain bibble-babble." },
    { r = {"MALVOLIO"}, t = "Sir Topas!" },
    { r = {"CLOWN"}, t = "Maintain no words with him, good fellow.", d = "As Sir Topas" },
    { r = {"CLOWN"}, t = "Who, I, sir? not I, sir. God buy you, good Sir Topas.", d = "As himself" },
    { r = {"CLOWN"}, t = "Marry, amen.", d = "As Sir Topas" },
    { r = {"CLOWN"}, t = "I will sir, I will.", d = "As himself" },
    { r = {"MALVOLIO"}, t = "Fool, fool, fool, I say!" },
    { r = {"CLOWN"}, t = "Alas, sir, be patient." },
    { r = {"CLOWN"}, t = "What say you, sir?" },
    { r = {"CLOWN"}, t = "I am shent for speaking to you." },
    { r = {"MALVOLIO"}, t = "Good fool, help me to some light and some paper." },
    { r = {"MALVOLIO"}, t = "I tell thee I am as well in my wits as any man in Illyria." },
    { r = {"CLOWN"}, t = "Well-a-day that you were, sir!" },
    { r = {"MALVOLIO"}, t = "By this hand, I am." },
    { r = {"MALVOLIO"}, t = "Good fool, some ink, paper, and light, and convey what I will set down to my lady." },
    { r = {"MALVOLIO"}, t = "It shall advantage thee more than ever the bearing of letter did." },
    { r = {"CLOWN"}, t = "I will help you to’t." },
    { r = {"CLOWN"}, t = "But tell me true, are you not mad indeed? or do you but counterfeit?" },
    { r = {"MALVOLIO"}, t = "Believe me, I am not. I tell thee true." },
    { r = {"CLOWN"}, t = "Nay, I’ll ne’er believe a madman till I see his brains." },
    { r = {"CLOWN"}, t = "I will fetch you light, and paper, and ink." },
    { r = {"MALVOLIO"}, t = "Fool, I’ll requite it in the highest degree: I prithee be gone." },
    { r = {"CLOWN"}, t = "I am gone, sir, and anon, sir,", d = "Singing" },
    { r = {"CLOWN"}, t = "I’ll be with you again," },
    { r = {"CLOWN"}, t = "In a trice, like to the old Vice," },
    { r = {"CLOWN"}, t = "Your need to sustain;" },
    { r = {"CLOWN"}, t = "Who with dagger of lath, in his rage and his wrath," },
    { r = {"CLOWN"}, t = "Cries ‘ah, ha!’ to the devil:" },
    { r = {"CLOWN"}, t = "Like a mad lad, ‘Pare thy nails, dad." },
    { r = {"CLOWN"}, t = "Adieu, goodman devil.’" },
    { d = "Exit" },
    { d = "Act 4, Scene 3. Olivia’s Garden.", h = true },
    { d = "Enter Sebastian" },
    { r = {"SEBASTIAN"}, t = "This is the air; that is the glorious sun," },
    { r = {"SEBASTIAN"}, t = "This pearl she gave me, I do feel’t and see’t," },
    { r = {"SEBASTIAN"}, t = "And though ’tis wonder that enwraps me thus," },
    { r = {"SEBASTIAN"}, t = "Yet ’tis not madness. Where’s Antonio, then?" },
    { r = {"SEBASTIAN"}, t = "I could not find him at the Elephant," },
    { r = {"SEBASTIAN"}, t = "Yet there he was, and there I found this credit," },
    { r = {"SEBASTIAN"}, t = "That he did range the town to seek me out." },
    { r = {"SEBASTIAN"}, t = "His counsel now might do me golden service." },
    { r = {"SEBASTIAN"}, t = "For though my soul disputes well with my sense" },
    { r = {"SEBASTIAN"}, t = "That this may be some error, but no madness," },
    { r = {"SEBASTIAN"}, t = "Yet doth this accident and flood of fortune" },
    { r = {"SEBASTIAN"}, t = "So far exceed all instance, all discourse," },
    { r = {"SEBASTIAN"}, t = "That I am ready to distrust mine eyes" },
    { r = {"SEBASTIAN"}, t = "And wrangle with my reason that persuades me" },
    { r = {"SEBASTIAN"}, t = "To any other trust but that I am mad," },
    { r = {"SEBASTIAN"}, t = "Or else the lady’s mad; yet if ’twere so," },
    { r = {"SEBASTIAN"}, t = "She could not sway her house, command her followers," },
    { r = {"SEBASTIAN"}, t = "Take and give back affairs and their dispatch," },
    { r = {"SEBASTIAN"}, t = "With such a smooth, discreet, and stable bearing" },
    { r = {"SEBASTIAN"}, t = "As I perceive she does. There’s something in’t" },
    { r = {"SEBASTIAN"}, t = "That is deceivable. But here the lady comes." },
    { d = "Enter Olivia and a Priest" },
    { r = {"OLIVIA"}, t = "Blame not this haste of mine. If you mean well," },
    { r = {"OLIVIA"}, t = "Now go with me and with this holy man" },
    { r = {"OLIVIA"}, t = "Into the chantry by: there, before him" },
    { r = {"OLIVIA"}, t = "And underneath that consecrated roof," },
    { r = {"OLIVIA"}, t = "Plight me the full assurance of your faith," },
    { r = {"OLIVIA"}, t = "That my most jealous and too doubtful soul" },
    { r = {"OLIVIA"}, t = "May live at peace. He shall conceal it" },
    { r = {"OLIVIA"}, t = "Whiles you are willing it shall come to note," },
    { r = {"OLIVIA"}, t = "What time we will our celebration keep" },
    { r = {"OLIVIA"}, t = "According to my birth. What do you say?" },
    { r = {"SEBASTIAN"}, t = "I’ll follow this good man, and go with you," },
    { r = {"SEBASTIAN"}, t = "And having sworn truth, ever will be true." },
    { r = {"OLIVIA"}, t = "Then lead the way, good father, and heavens so shine," },
    { r = {"OLIVIA"}, t = "That they may fairly note this act of mine!" },
    { d = "Exeunt" },
    { d = "Act 5, Scene 1. The Street before Olivia’s House.", h = true },
    { d = "Enter Clown and Fabian" },
    { r = {"FABIAN"}, t = "Now, as thou lov’st me, let me see his letter." },
    { r = {"CLOWN"}, t = "Good Master Fabian, grant me another request." },
    { r = {"FABIAN"}, t = "Anything." },
    { r = {"CLOWN"}, t = "Do not desire to see this letter." },
    { r = {"FABIAN"}, t = "This is to give a dog, and in recompense desire my dog again." },
    { d = "Enter Duke, Viola, Curio and Lords" },
    { r = {"ORSINO"}, t = "Belong you to the Lady Olivia, friends?" },
    { r = {"CLOWN"}, t = "Ay, sir, we are some of her trappings." },
    { r = {"ORSINO"}, t = "I know thee well. How dost thou, my good fellow?" },
    { r = {"CLOWN"}, t = "Truly, sir, the better for my foes, and the worse for my friends." },
    { r = {"ORSINO"}, t = "Just the contrary; the better for thy friends." },
    { r = {"CLOWN"}, t = "No, sir, the worse." },
    { r = {"ORSINO"}, t = "How can that be?" },
    { r = {"CLOWN"}, t = "Marry, sir, they praise me, and make an ass of me." },
    { r = {"CLOWN"}, t = "Now my foes tell me plainly I am an ass: so that by my foes, sir, I profit in the knowledge of myself, and by my friends I am abused." },
    { r = {"CLOWN"}, t = "So that, conclusions to be as kisses, if your four negatives make your two affirmatives, why then, the worse for my friends, and the better for my foes." },
    { r = {"ORSINO"}, t = "Why, this is excellent." },
    { r = {"CLOWN"}, t = "By my troth, sir, no; though it please you to be one of my friends." },
    { r = {"ORSINO"}, t = "Thou shalt not be the worse for me; there’s gold." },
    { r = {"CLOWN"}, t = "But that it would be double-dealing, sir, I would you could make it another." },
    { r = {"ORSINO"}, t = "O, you give me ill counsel." },
    { r = {"CLOWN"}, t = "Put your grace in your pocket, sir, for this once, and let your flesh and blood obey it." },
    { r = {"ORSINO"}, t = "Well, I will be so much a sinner to be a double-dealer: there’s another." },
    { r = {"CLOWN"}, t = "Primo, secundo, tertio, is a good play, and the old saying is, the third pays for all; the triplex, sir, is a good tripping measure; or the bells of Saint Bennet, sir, may put you in mind—one, two, three." },
    { r = {"ORSINO"}, t = "You can fool no more money out of me at this throw." },
    { r = {"ORSINO"}, t = "If you will let your lady know I am here to speak with her, and bring her along with you, it may awake my bounty further." },
    { r = {"CLOWN"}, t = "Marry, sir, lullaby to your bounty till I come again." },
    { r = {"CLOWN"}, t = "I go, sir, but I would not have you to think that my desire of having is the sin of covetousness: but as you say, sir, let your bounty take a nap, I will awake it anon." },
    { d = "Exit Clown" },
    { d = "Enter Antonio and Officers" },
    { r = {"VIOLA"}, t = "Here comes the man, sir, that did rescue me." },
    { r = {"ORSINO"}, t = "That face of his I do remember well." },
    { r = {"ORSINO"}, t = "Yet when I saw it last it was besmear’d" },
    { r = {"ORSINO"}, t = "As black as Vulcan, in the smoke of war." },
    { r = {"ORSINO"}, t = "A baubling vessel was he captain of," },
    { r = {"ORSINO"}, t = "For shallow draught and bulk unprizable," },
    { r = {"ORSINO"}, t = "With which such scathful grapple did he make" },
    { r = {"ORSINO"}, t = "With the most noble bottom of our fleet," },
    { r = {"ORSINO"}, t = "That very envy and the tongue of loss" },
    { r = {"ORSINO"}, t = "Cried fame and honour on him. What’s the matter?" },
    { r = {"FIRST OFFICER"}, t = "Orsino, this is that Antonio" },
    { r = {"FIRST OFFICER"}, t = "That took the Phoenix and her fraught from Candy," },
    { r = {"FIRST OFFICER"}, t = "And this is he that did the Tiger board" },
    { r = {"FIRST OFFICER"}, t = "When your young nephew Titus lost his leg." },
    { r = {"FIRST OFFICER"}, t = "Here in the streets, desperate of shame and state," },
    { r = {"FIRST OFFICER"}, t = "In private brabble did we apprehend him." },
    { r = {"VIOLA"}, t = "He did me kindness, sir; drew on my side," },
    { r = {"VIOLA"}, t = "But in conclusion, put strange speech upon me." },
    { r = {"VIOLA"}, t = "I know not what ’twas, but distraction." },
    { r = {"ORSINO"}, t = "Notable pirate, thou salt-water thief," },
    { r = {"ORSINO"}, t = "What foolish boldness brought thee to their mercies," },
    { r = {"ORSINO"}, t = "Whom thou, in terms so bloody and so dear," },
    { r = {"ORSINO"}, t = "Hast made thine enemies?" },
    { r = {"ANTONIO"}, t = "Orsino, noble sir," },
    { r = {"ANTONIO"}, t = "Be pleased that I shake off these names you give me:" },
    { r = {"ANTONIO"}, t = "Antonio never yet was thief or pirate," },
    { r = {"ANTONIO"}, t = "Though, I confess, on base and ground enough," },
    { r = {"ANTONIO"}, t = "Orsino’s enemy. A witchcraft drew me hither:" },
    { r = {"ANTONIO"}, t = "That most ingrateful boy there by your side" },
    { r = {"ANTONIO"}, t = "From the rude sea’s enraged and foamy mouth" },
    { r = {"ANTONIO"}, t = "Did I redeem; a wreck past hope he was." },
    { r = {"ANTONIO"}, t = "His life I gave him, and did thereto add" },
    { r = {"ANTONIO"}, t = "My love, without retention or restraint," },
    { r = {"ANTONIO"}, t = "All his in dedication. For his sake" },
    { r = {"ANTONIO"}, t = "Did I expose myself, pure for his love," },
    { r = {"ANTONIO"}, t = "Into the danger of this adverse town;" },
    { r = {"ANTONIO"}, t = "Drew to defend him when he was beset;" },
    { r = {"ANTONIO"}, t = "Where being apprehended, his false cunning" },
    { r = {"ANTONIO"}, t = "(Not meaning to partake with me in danger)" },
    { r = {"ANTONIO"}, t = "Taught him to face me out of his acquaintance," },
    { r = {"ANTONIO"}, t = "And grew a twenty years’ removed thing" },
    { r = {"ANTONIO"}, t = "While one would wink; denied me mine own purse," },
    { r = {"ANTONIO"}, t = "Which I had recommended to his use" },
    { r = {"ANTONIO"}, t = "Not half an hour before." },
    { r = {"VIOLA"}, t = "How can this be?" },
    { r = {"ORSINO"}, t = "When came he to this town?" },
    { r = {"ANTONIO"}, t = "Today, my lord; and for three months before," },
    { r = {"ANTONIO"}, t = "No int’rim, not a minute’s vacancy," },
    { r = {"ANTONIO"}, t = "Both day and night did we keep company." },
    { d = "Enter Olivia and Attendants" },
    { r = {"ORSINO"}, t = "Here comes the Countess, now heaven walks on earth." },
    { r = {"ORSINO"}, t = "But for thee, fellow, fellow, thy words are madness." },
    { r = {"ORSINO"}, t = "Three months this youth hath tended upon me;" },
    { r = {"ORSINO"}, t = "But more of that anon. Take him aside." },
    { r = {"OLIVIA"}, t = "What would my lord, but that he may not have," },
    { r = {"OLIVIA"}, t = "Wherein Olivia may seem serviceable?" },
    { r = {"OLIVIA"}, t = "Cesario, you do not keep promise with me." },
    { r = {"VIOLA"}, t = "Madam?" },
    { r = {"ORSINO"}, t = "Gracious Olivia" },
    { r = {"OLIVIA"}, t = "What do you say, Cesario? Good my lord" },
    { r = {"VIOLA"}, t = "My lord would speak, my duty hushes me." },
    { r = {"OLIVIA"}, t = "If it be aught to the old tune, my lord," },
    { r = {"OLIVIA"}, t = "It is as fat and fulsome to mine ear" },
    { r = {"OLIVIA"}, t = "As howling after music." },
    { r = {"ORSINO"}, t = "Still so cruel?" },
    { r = {"OLIVIA"}, t = "Still so constant, lord." },
    { r = {"ORSINO"}, t = "What, to perverseness? You uncivil lady," },
    { r = {"ORSINO"}, t = "To whose ingrate and unauspicious altars" },
    { r = {"ORSINO"}, t = "My soul the faithfull’st off’rings hath breathed out" },
    { r = {"ORSINO"}, t = "That e’er devotion tender’d! What shall I do?" },
    { r = {"OLIVIA"}, t = "Even what it please my lord that shall become him." },
    { r = {"ORSINO"}, t = "Why should I not, had I the heart to do it," },
    { r = {"ORSINO"}, t = "Like to the Egyptian thief at point of death," },
    { r = {"ORSINO"}, t = "Kill what I love?—a savage jealousy" },
    { r = {"ORSINO"}, t = "That sometime savours nobly. But hear me this:" },
    { r = {"ORSINO"}, t = "Since you to non-regardance cast my faith," },
    { r = {"ORSINO"}, t = "And that I partly know the instrument" },
    { r = {"ORSINO"}, t = "That screws me from my true place in your favour," },
    { r = {"ORSINO"}, t = "Live you the marble-breasted tyrant still." },
    { r = {"ORSINO"}, t = "But this your minion, whom I know you love," },
    { r = {"ORSINO"}, t = "And whom, by heaven I swear, I tender dearly," },
    { r = {"ORSINO"}, t = "Him will I tear out of that cruel eye" },
    { r = {"ORSINO"}, t = "Where he sits crowned in his master’s spite.—" },
    { r = {"ORSINO"}, t = "Come, boy, with me; my thoughts are ripe in mischief:" },
    { r = {"ORSINO"}, t = "I’ll sacrifice the lamb that I do love," },
    { r = {"ORSINO"}, t = "To spite a raven’s heart within a dove." },
    { r = {"VIOLA"}, t = "And I, most jocund, apt, and willingly," },
    { r = {"VIOLA"}, t = "To do you rest, a thousand deaths would die." },
    { r = {"OLIVIA"}, t = "Where goes Cesario?" },
    { r = {"VIOLA"}, t = "After him I love" },
    { r = {"VIOLA"}, t = "More than I love these eyes, more than my life," },
    { r = {"VIOLA"}, t = "More, by all mores, than e’er I shall love wife." },
    { r = {"VIOLA"}, t = "If I do feign, you witnesses above" },
    { r = {"VIOLA"}, t = "Punish my life for tainting of my love." },
    { r = {"OLIVIA"}, t = "Ah me, detested! how am I beguil’d!" },
    { r = {"VIOLA"}, t = "Who does beguile you? Who does do you wrong?" },
    { r = {"OLIVIA"}, t = "Hast thou forgot thyself? Is it so long?" },
    { r = {"OLIVIA"}, t = "Call forth the holy father." },
    { d = "Exit an Attendant" },
    { r = {"ORSINO"}, t = "Come, away!", d = "To Viola" },
    { r = {"OLIVIA"}, t = "Whither, my lord? Cesario, husband, stay." },
    { r = {"ORSINO"}, t = "Husband?" },
    { r = {"OLIVIA"}, t = "Ay, husband. Can he that deny?" },
    { r = {"ORSINO"}, t = "Her husband, sirrah?" },
    { r = {"VIOLA"}, t = "No, my lord, not I." },
    { r = {"OLIVIA"}, t = "Alas, it is the baseness of thy fear" },
    { r = {"OLIVIA"}, t = "That makes thee strangle thy propriety." },
    { r = {"OLIVIA"}, t = "Fear not, Cesario, take thy fortunes up." },
    { r = {"OLIVIA"}, t = "Be that thou know’st thou art, and then thou art" },
    { r = {"OLIVIA"}, t = "As great as that thou fear’st." },
    { d = "Enter Priest" },
    { r = {"OLIVIA"}, t = "O, welcome, father!" },
    { r = {"OLIVIA"}, t = "Father, I charge thee, by thy reverence" },
    { r = {"OLIVIA"}, t = "Here to unfold—though lately we intended" },
    { r = {"OLIVIA"}, t = "To keep in darkness what occasion now" },
    { r = {"OLIVIA"}, t = "Reveals before ’tis ripe—what thou dost know" },
    { r = {"OLIVIA"}, t = "Hath newly passed between this youth and me." },
    { r = {"PRIEST"}, t = "A contract of eternal bond of love," },
    { r = {"PRIEST"}, t = "Confirmed by mutual joinder of your hands," },
    { r = {"PRIEST"}, t = "Attested by the holy close of lips," },
    { r = {"PRIEST"}, t = "Strengthen’d by interchangement of your rings," },
    { r = {"PRIEST"}, t = "And all the ceremony of this compact" },
    { r = {"PRIEST"}, t = "Sealed in my function, by my testimony;" },
    { r = {"PRIEST"}, t = "Since when, my watch hath told me, toward my grave," },
    { r = {"PRIEST"}, t = "I have travelled but two hours." },
    { r = {"ORSINO"}, t = "O thou dissembling cub! What wilt thou be" },
    { r = {"ORSINO"}, t = "When time hath sowed a grizzle on thy case?" },
    { r = {"ORSINO"}, t = "Or will not else thy craft so quickly grow" },
    { r = {"ORSINO"}, t = "That thine own trip shall be thine overthrow?" },
    { r = {"ORSINO"}, t = "Farewell, and take her; but direct thy feet" },
    { r = {"ORSINO"}, t = "Where thou and I henceforth may never meet." },
    { r = {"VIOLA"}, t = "My lord, I do protest" },
    { r = {"OLIVIA"}, t = "O, do not swear." },
    { r = {"OLIVIA"}, t = "Hold little faith, though thou has too much fear." },
    { d = "Enter Sir Andrew" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "For the love of God, a surgeon! Send one presently to Sir Toby." },
    { r = {"OLIVIA"}, t = "What’s the matter?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Has broke my head across, and has given Sir Toby a bloody coxcomb too." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "For the love of God, your help!" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I had rather than forty pound I were at home." },
    { r = {"OLIVIA"}, t = "Who has done this, Sir Andrew?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "The Count’s gentleman, one Cesario." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "We took him for a coward, but he’s the very devil incardinate." },
    { r = {"ORSINO"}, t = "My gentleman, Cesario?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "’Od’s lifelings, here he is!—You broke my head for nothing; and that that I did, I was set on to do’t by Sir Toby." },
    { r = {"VIOLA"}, t = "Why do you speak to me? I never hurt you:" },
    { r = {"VIOLA"}, t = "You drew your sword upon me without cause," },
    { r = {"VIOLA"}, t = "But I bespake you fair and hurt you not." },
    { d = "Enter Sir Toby, drunk, led by the Clown" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "If a bloody coxcomb be a hurt, you have hurt me." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I think you set nothing by a bloody coxcomb." },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "Here comes Sir Toby halting, you shall hear more: but if he had not been in drink, he would have tickled you othergates than he did." },
    { r = {"ORSINO"}, t = "How now, gentleman? How is’t with you?" },
    { r = {"SIR TOBY BELCH"}, t = "That’s all one; ’has hurt me, and there’s th’ end on’t." },
    { r = {"SIR TOBY BELCH"}, t = "Sot, didst see Dick Surgeon, sot?" },
    { r = {"CLOWN"}, t = "O, he’s drunk, Sir Toby, an hour agone; his eyes were set at eight i’ th’ morning." },
    { r = {"SIR TOBY BELCH"}, t = "Then he’s a rogue, and a passy measures pavin. I hate a drunken rogue." },
    { r = {"OLIVIA"}, t = "Away with him. Who hath made this havoc with them?" },
    { r = {"SIR ANDREW AGUECHEEK"}, t = "I’ll help you, Sir Toby, because we’ll be dressed together." },
    { r = {"SIR TOBY BELCH"}, t = "Will you help?" },
    { r = {"SIR TOBY BELCH"}, t = "An ass-head, and a coxcomb, and a knave, a thin-faced knave, a gull?" },
    { r = {"OLIVIA"}, t = "Get him to bed, and let his hurt be looked to." },
    { d = "Exeunt Clown, Fabian, Sir Toby and Sir Andrew" },
    { d = "Enter Sebastian" },
    { r = {"SEBASTIAN"}, t = "I am sorry, madam, I have hurt your kinsman;" },
    { r = {"SEBASTIAN"}, t = "But had it been the brother of my blood," },
    { r = {"SEBASTIAN"}, t = "I must have done no less with wit and safety." },
    { r = {"SEBASTIAN"}, t = "You throw a strange regard upon me, and by that" },
    { r = {"SEBASTIAN"}, t = "I do perceive it hath offended you." },
    { r = {"SEBASTIAN"}, t = "Pardon me, sweet one, even for the vows" },
    { r = {"SEBASTIAN"}, t = "We made each other but so late ago." },
    { r = {"ORSINO"}, t = "One face, one voice, one habit, and two persons!" },
    { r = {"ORSINO"}, t = "A natural perspective, that is, and is not!" },
    { r = {"SEBASTIAN"}, t = "Antonio, O my dear Antonio!" },
    { r = {"SEBASTIAN"}, t = "How have the hours rack’d and tortur’d me" },
    { r = {"SEBASTIAN"}, t = "Since I have lost thee." },
    { r = {"ANTONIO"}, t = "Sebastian are you?" },
    { r = {"SEBASTIAN"}, t = "Fear’st thou that, Antonio?" },
    { r = {"ANTONIO"}, t = "How have you made division of yourself?" },
    { r = {"ANTONIO"}, t = "An apple cleft in two is not more twin" },
    { r = {"ANTONIO"}, t = "Than these two creatures. Which is Sebastian?" },
    { r = {"OLIVIA"}, t = "Most wonderful!" },
    { r = {"SEBASTIAN"}, t = "Do I stand there? I never had a brother:" },
    { r = {"SEBASTIAN"}, t = "Nor can there be that deity in my nature" },
    { r = {"SEBASTIAN"}, t = "Of here and everywhere. I had a sister," },
    { r = {"SEBASTIAN"}, t = "Whom the blind waves and surges have devoured." },
    { r = {"SEBASTIAN"}, t = "Of charity, what kin are you to me?" },
    { r = {"SEBASTIAN"}, t = "What countryman? What name? What parentage?" },
    { r = {"VIOLA"}, t = "Of Messaline: Sebastian was my father;" },
    { r = {"VIOLA"}, t = "Such a Sebastian was my brother too:" },
    { r = {"VIOLA"}, t = "So went he suited to his watery tomb." },
    { r = {"VIOLA"}, t = "If spirits can assume both form and suit," },
    { r = {"VIOLA"}, t = "You come to fright us." },
    { r = {"SEBASTIAN"}, t = "A spirit I am indeed," },
    { r = {"SEBASTIAN"}, t = "But am in that dimension grossly clad," },
    { r = {"SEBASTIAN"}, t = "Which from the womb I did participate." },
    { r = {"SEBASTIAN"}, t = "Were you a woman, as the rest goes even," },
    { r = {"SEBASTIAN"}, t = "I should my tears let fall upon your cheek," },
    { r = {"SEBASTIAN"}, t = "And say, ‘Thrice welcome, drowned Viola.’" },
    { r = {"VIOLA"}, t = "My father had a mole upon his brow." },
    { r = {"SEBASTIAN"}, t = "And so had mine." },
    { r = {"VIOLA"}, t = "And died that day when Viola from her birth" },
    { r = {"VIOLA"}, t = "Had numbered thirteen years." },
    { r = {"SEBASTIAN"}, t = "O, that record is lively in my soul!" },
    { r = {"SEBASTIAN"}, t = "He finished indeed his mortal act" },
    { r = {"SEBASTIAN"}, t = "That day that made my sister thirteen years." },
    { r = {"VIOLA"}, t = "If nothing lets to make us happy both" },
    { r = {"VIOLA"}, t = "But this my masculine usurp’d attire," },
    { r = {"VIOLA"}, t = "Do not embrace me till each circumstance" },
    { r = {"VIOLA"}, t = "Of place, time, fortune, do cohere and jump" },
    { r = {"VIOLA"}, t = "That I am Viola; which to confirm," },
    { r = {"VIOLA"}, t = "I’ll bring you to a captain in this town," },
    { r = {"VIOLA"}, t = "Where lie my maiden weeds; by whose gentle help" },
    { r = {"VIOLA"}, t = "I was preserv’d to serve this noble count." },
    { r = {"VIOLA"}, t = "All the occurrence of my fortune since" },
    { r = {"VIOLA"}, t = "Hath been between this lady and this lord." },
    { r = {"SEBASTIAN"}, t = "So comes it, lady, you have been mistook.", d = "To Olivia" },
    { r = {"SEBASTIAN"}, t = "But nature to her bias drew in that." },
    { r = {"SEBASTIAN"}, t = "You would have been contracted to a maid;" },
    { r = {"SEBASTIAN"}, t = "Nor are you therein, by my life, deceived:" },
    { r = {"SEBASTIAN"}, t = "You are betroth’d both to a maid and man." },
    { r = {"ORSINO"}, t = "Be not amazed; right noble is his blood." },
    { r = {"ORSINO"}, t = "If this be so, as yet the glass seems true," },
    { r = {"ORSINO"}, t = "I shall have share in this most happy wreck." },
    { r = {"ORSINO"}, t = "Boy, thou hast said to me a thousand times", d = "To Viola" },
    { r = {"ORSINO"}, t = "Thou never shouldst love woman like to me." },
    { r = {"VIOLA"}, t = "And all those sayings will I over-swear," },
    { r = {"VIOLA"}, t = "And all those swearings keep as true in soul" },
    { r = {"VIOLA"}, t = "As doth that orbed continent the fire" },
    { r = {"VIOLA"}, t = "That severs day from night." },
    { r = {"ORSINO"}, t = "Give me thy hand," },
    { r = {"ORSINO"}, t = "And let me see thee in thy woman’s weeds." },
    { r = {"VIOLA"}, t = "The captain that did bring me first on shore" },
    { r = {"VIOLA"}, t = "Hath my maid’s garments. He, upon some action," },
    { r = {"VIOLA"}, t = "Is now in durance, at Malvolio’s suit," },
    { r = {"VIOLA"}, t = "A gentleman and follower of my lady’s." },
    { r = {"OLIVIA"}, t = "He shall enlarge him. Fetch Malvolio hither." },
    { r = {"OLIVIA"}, t = "And yet, alas, now I remember me," },
    { r = {"OLIVIA"}, t = "They say, poor gentleman, he’s much distract." },
    { d = "Enter Clown, with a letter and Fabian" },
    { r = {"OLIVIA"}, t = "A most extracting frenzy of mine own" },
    { r = {"OLIVIA"}, t = "From my remembrance clearly banished his." },
    { r = {"OLIVIA"}, t = "How does he, sirrah?" },
    { r = {"CLOWN"}, t = "Truly, madam, he holds Belzebub at the stave’s end as well as a man in his case may do." },
    { r = {"CLOWN"}, t = "Has here writ a letter to you." },
    { r = {"CLOWN"}, t = "I should have given it you today morning, but as a madman’s epistles are no gospels, so it skills not much when they are delivered." },
    { r = {"OLIVIA"}, t = "Open ’t, and read it." },
    { r = {"CLOWN"}, t = "Look then to be well edified, when the fool delivers the madman." },
    { r = {"CLOWN"}, t = "By the Lord, madam," },
    { r = {"OLIVIA"}, t = "How now, art thou mad?" },
    { r = {"CLOWN"}, t = "No, madam, I do but read madness: an your ladyship will have it as it ought to be, you must allow vox." },
    { r = {"OLIVIA"}, t = "Prithee, read i’ thy right wits." },
    { r = {"CLOWN"}, t = "So I do, madonna." },
    { r = {"CLOWN"}, t = "But to read his right wits is to read thus; therefore perpend, my princess, and give ear." },
    { r = {"OLIVIA"}, t = "Read it you, sirrah.", d = "To Fabian" },
    { r = {"FABIAN"}, t = "By the Lord, madam, you wrong me, and the world shall know it.", d = "Reads" },
    { r = {"FABIAN"}, t = "Though you have put me into darkness and given your drunken cousin rule over me, yet have I the benefit of my senses as well as your ladyship." },
    { r = {"FABIAN"}, t = "I have your own letter that induced me to the semblance I put on; with the which I doubt not but to do myself much right or you much shame." },
    { r = {"FABIAN"}, t = "Think of me as you please." },
    { r = {"FABIAN"}, t = "I leave my duty a little unthought of, and speak out of my injury." },
    { r = {"FABIAN"}, t = "The madly-used Malvolio." },
    { r = {"OLIVIA"}, t = "Did he write this?" },
    { r = {"CLOWN"}, t = "Ay, madam." },
    { r = {"ORSINO"}, t = "This savours not much of distraction." },
    { r = {"OLIVIA"}, t = "See him delivered, Fabian, bring him hither." },
    { d = "Exit Fabian" },
    { r = {"OLIVIA"}, t = "My lord, so please you, these things further thought on," },
    { r = {"OLIVIA"}, t = "To think me as well a sister, as a wife," },
    { r = {"OLIVIA"}, t = "One day shall crown th’ alliance on’t, so please you," },
    { r = {"OLIVIA"}, t = "Here at my house, and at my proper cost." },
    { r = {"ORSINO"}, t = "Madam, I am most apt t’ embrace your offer." },
    { r = {"ORSINO"}, t = "Your master quits you; and for your service done him,", d = "To Viola" },
    { r = {"ORSINO"}, t = "So much against the mettle of your sex," },
    { r = {"ORSINO"}, t = "So far beneath your soft and tender breeding," },
    { r = {"ORSINO"}, t = "And since you call’d me master for so long," },
    { r = {"ORSINO"}, t = "Here is my hand; you shall from this time be" },
    { r = {"ORSINO"}, t = "Your master’s mistress." },
    { r = {"OLIVIA"}, t = "A sister? You are she." },
    { d = "Enter Fabian and Malvolio" },
    { r = {"ORSINO"}, t = "Is this the madman?" },
    { r = {"OLIVIA"}, t = "Ay, my lord, this same." },
    { r = {"OLIVIA"}, t = "How now, Malvolio?" },
    { r = {"MALVOLIO"}, t = "Madam, you have done me wrong," },
    { r = {"MALVOLIO"}, t = "Notorious wrong." },
    { r = {"OLIVIA"}, t = "Have I, Malvolio? No." },
    { r = {"MALVOLIO"}, t = "Lady, you have. Pray you peruse that letter." },
    { r = {"MALVOLIO"}, t = "You must not now deny it is your hand," },
    { r = {"MALVOLIO"}, t = "Write from it, if you can, in hand, or phrase," },
    { r = {"MALVOLIO"}, t = "Or say ’tis not your seal, not your invention:" },
    { r = {"MALVOLIO"}, t = "You can say none of this. Well, grant it then," },
    { r = {"MALVOLIO"}, t = "And tell me, in the modesty of honour," },
    { r = {"MALVOLIO"}, t = "Why you have given me such clear lights of favour," },
    { r = {"MALVOLIO"}, t = "Bade me come smiling and cross-garter’d to you," },
    { r = {"MALVOLIO"}, t = "To put on yellow stockings, and to frown" },
    { r = {"MALVOLIO"}, t = "Upon Sir Toby, and the lighter people;" },
    { r = {"MALVOLIO"}, t = "And acting this in an obedient hope," },
    { r = {"MALVOLIO"}, t = "Why have you suffer’d me to be imprison’d," },
    { r = {"MALVOLIO"}, t = "Kept in a dark house, visited by the priest," },
    { r = {"MALVOLIO"}, t = "And made the most notorious geck and gull" },
    { r = {"MALVOLIO"}, t = "That e’er invention played on? Tell me why?" },
    { r = {"OLIVIA"}, t = "Alas, Malvolio, this is not my writing," },
    { r = {"OLIVIA"}, t = "Though I confess, much like the character:" },
    { r = {"OLIVIA"}, t = "But out of question, ’tis Maria’s hand." },
    { r = {"OLIVIA"}, t = "And now I do bethink me, it was she" },
    { r = {"OLIVIA"}, t = "First told me thou wast mad; then cam’st in smiling," },
    { r = {"OLIVIA"}, t = "And in such forms which here were presuppos’d" },
    { r = {"OLIVIA"}, t = "Upon thee in the letter. Prithee, be content." },
    { r = {"OLIVIA"}, t = "This practice hath most shrewdly pass’d upon thee." },
    { r = {"OLIVIA"}, t = "But when we know the grounds and authors of it," },
    { r = {"OLIVIA"}, t = "Thou shalt be both the plaintiff and the judge" },
    { r = {"OLIVIA"}, t = "Of thine own cause." },
    { r = {"FABIAN"}, t = "Good madam, hear me speak," },
    { r = {"FABIAN"}, t = "And let no quarrel, nor no brawl to come," },
    { r = {"FABIAN"}, t = "Taint the condition of this present hour," },
    { r = {"FABIAN"}, t = "Which I have wonder’d at. In hope it shall not," },
    { r = {"FABIAN"}, t = "Most freely I confess, myself and Toby" },
    { r = {"FABIAN"}, t = "Set this device against Malvolio here," },
    { r = {"FABIAN"}, t = "Upon some stubborn and uncourteous parts" },
    { r = {"FABIAN"}, t = "We had conceiv’d against him. Maria writ" },
    { r = {"FABIAN"}, t = "The letter, at Sir Toby’s great importance," },
    { r = {"FABIAN"}, t = "In recompense whereof he hath married her." },
    { r = {"FABIAN"}, t = "How with a sportful malice it was follow’d" },
    { r = {"FABIAN"}, t = "May rather pluck on laughter than revenge," },
    { r = {"FABIAN"}, t = "If that the injuries be justly weigh’d" },
    { r = {"FABIAN"}, t = "That have on both sides passed." },
    { r = {"OLIVIA"}, t = "Alas, poor fool, how have they baffled thee!" },
    { r = {"CLOWN"}, t = "Why, ‘some are born great, some achieve greatness, and some have greatness thrown upon them.’" },
    { r = {"CLOWN"}, t = "I was one, sir, in this interlude, one Sir Topas, sir, but that’s all one." },
    { r = {"CLOWN"}, t = "‘By the Lord, fool, I am not mad.’" },
    { r = {"CLOWN"}, t = "But do you remember?" },
    { r = {"CLOWN"}, t = "‘Madam, why laugh you at such a barren rascal?" },
    { r = {"CLOWN"}, t = "And you smile not, he’s gagged’?" },
    { r = {"CLOWN"}, t = "And thus the whirligig of time brings in his revenges." },
    { r = {"MALVOLIO"}, t = "I’ll be revenged on the whole pack of you." },
    { d = "Exit" },
    { r = {"OLIVIA"}, t = "He hath been most notoriously abus’d." },
    { r = {"ORSINO"}, t = "Pursue him, and entreat him to a peace:" },
    { r = {"ORSINO"}, t = "He hath not told us of the captain yet." },
    { r = {"ORSINO"}, t = "When that is known, and golden time convents," },
    { r = {"ORSINO"}, t = "A solemn combination shall be made" },
    { r = {"ORSINO"}, t = "Of our dear souls.—Meantime, sweet sister," },
    { r = {"ORSINO"}, t = "We will not part from hence.—Cesario, come:" },
    { r = {"ORSINO"}, t = "For so you shall be while you are a man;" },
    { r = {"ORSINO"}, t = "But when in other habits you are seen," },
    { r = {"ORSINO"}, t = "Orsino’s mistress, and his fancy’s queen." },
    { d = "Exeunt" },
    { r = {"CLOWN"}, t = "When that I was and a little tiny boy,", d = "sings" },
    { r = {"CLOWN"}, t = "With hey, ho, the wind and the rain," },
    { r = {"CLOWN"}, t = "A foolish thing was but a toy," },
    { r = {"CLOWN"}, t = "For the rain it raineth every day." },
    { r = {"CLOWN"}, t = "But when I came to man’s estate," },
    { r = {"CLOWN"}, t = "With hey, ho, the wind and the rain," },
    { r = {"CLOWN"}, t = "’Gainst knaves and thieves men shut their gate," },
    { r = {"CLOWN"}, t = "For the rain it raineth every day." },
    { r = {"CLOWN"}, t = "But when I came, alas, to wive," },
    { r = {"CLOWN"}, t = "With hey, ho, the wind and the rain," },
    { r = {"CLOWN"}, t = "By swaggering could I never thrive," },
    { r = {"CLOWN"}, t = "For the rain it raineth every day." },
    { r = {"CLOWN"}, t = "But when I came unto my beds," },
    { r = {"CLOWN"}, t = "With hey, ho, the wind and the rain," },
    { r = {"CLOWN"}, t = "With toss-pots still had drunken heads," },
    { r = {"CLOWN"}, t = "For the rain it raineth every day." },
    { r = {"CLOWN"}, t = "A great while ago the world begun," },
    { r = {"CLOWN"}, t = "With hey, ho, the wind and the rain," },
    { r = {"CLOWN"}, t = "But that’s all one, our play is done," },
    { r = {"CLOWN"}, t = "And we’ll strive to please you every day." },
    { d = "Exit" },
  },
}
